p9=A.a(["\ub300\uc218","\uc9c0\uc218","\uc9c0\uc218\uc758\ud655\uc7a5","\uc2e4\uc218\uc9c0\uc218"],ai0)
p9=A.av(s2,A.a([A.au(A.a(["\ub300\uc218 > \uc9c0\uc218 > \uc9c0\uc218\uc758\ud655\uc7a5 > \uc2e4\uc218\uc9c0\uc218 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.r,A.a(["\uc9c0\uc218\uc758 \ud655\uc7a5\uc740 \uc790\uc5f0\uc218\uc5d0\uc11c \uc815\uc218\ub85c, \ub2e4\uc2dc \uc720\ub9ac\uc218\ub85c \ud655\uc7a5\ub418\ub294 \uacfc\uc815\uc744 \uac70\uccd0 \ucd5c\uc885\uc801\uc73c\ub85c \uc2e4\uc218 \uc804\uccb4\uc758 \ubc94\uc704\uae4c\uc9c0 \ub113\uc5b4\uc9d1\ub2c8\ub2e4. \uc2e4\uc218\uc9c0\uc218\ub780 \uc9c0\uc218 \uc790\ub9ac\uc5d0 \uc720\ub9ac\uc218\uac00 \uc544\ub2cc \ubb34\ub9ac\uc218(\uc608: $\\sqrt{2}, \\pi$ \ub4f1)\uac00 \uc624\ub294 \uacbd\uc6b0\ub97c \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc720\ub9ac\uc218 \uc9c0\uc218 $a^r$ ($a>0, r$\uc740 \uc720\ub9ac\uc218)\uac00 \uc815\uc758\ub420 \ub54c, \ubb34\ub9ac\uc218 \uc9c0\uc218 $a^x$ ($x$\ub294 \ubb34\ub9ac\uc218)\ub294 $x$\uc5d0 \ud55c\uc5c6\uc774 \uac00\uae4c\uc6cc\uc9c0\ub294 \uc720\ub9ac\uc218\ub4e4\uc758 \uc218\uc5f4\uc744 \uc774\uc6a9\ud558\uc5ec \uadf8 \uadf9\ud55c\uac12\uc73c\ub85c \uc815\uc758\ud569\ub2c8\ub2e4. \uc774\ub54c \ubc11 $a$\ub294 \ud56d\uc0c1 \uc591\uc218($a>0$)\uc5ec\uc57c \ud55c\ub2e4\ub294 \uc810\uc774 \ub9e4\uc6b0 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc2e4\uc218\uc9c0\uc218\uc5d0\uc11c\ub3c4 \uc9c0\uc218\ubc95\uce59\uc740 \uadf8\ub300\ub85c \uc131\ub9bd\ud569\ub2c8\ub2e4. $a>0, b>0$\uc774\uace0 $x, y$\uac00 \uc784\uc758\uc758 \uc2e4\uc218\uc77c \ub54c, \ub2e4\uc74c\uc758 \ud575\uc2ec \uacf5\uc2dd\ub4e4\uc774 \uc131\ub9bd\ud569\ub2c8\ub2e4. \uccab\uc9f8, $a^x \\cdot a^y = a^{x+y}$\uc774\uba70, \ub458\uc9f8, $(a^x)^y = a^{xy}$\uc785\ub2c8\ub2e4. \uc14b\uc9f8, $(ab)^x = a^x b^x$\uc774\uace0, \ub137\uc9f8, $a^x / a^y = a^{x-y}$\uc785\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc131\uc9c8\ub4e4\uc740 \uc9c0\uc218\uac00 \uc2e4\uc218 \ubc94\uc704\ub85c \ud655\uc7a5\ub418\uc5b4\ub3c4 \uc9c0\uc218\ubc95\uce59\uc774 \uc77c\uad00\ub418\uac8c \uc801\uc6a9\ub428\uc744 \ubcf4\uc5ec\uc8fc\uba70, \uc774\ub294 \ubcf5\uc7a1\ud55c \uc218\uc2dd\uc744 \uac04\uacb0\ud558\uac8c \uacc4\uc0b0\ud558\ub294 \uac15\ub825\ud55c \ub3c4\uad6c\uac00 \ub429\ub2c8\ub2e4.","\uc2e4\uc218\uc9c0\uc218\ub97c \ud65c\uc6a9\ud558\uba74 $2^{\\sqrt{2}}$\uc640 \uac19\uc774 \uc9c1\uad00\uc801\uc73c\ub85c \uacc4\uc0b0\ud558\uae30 \uc5b4\ub824\uc6b4 \uac12\ub3c4 \uc218\uc5f4\uc758 \uadf9\ud55c\uc744 \ud1b5\ud574 \uadf8 \uc704\uce58\ub97c \ud30c\uc545\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, $\\sqrt{2} \\approx 1.414...$\uc774\ubbc0\ub85c $2^{1.4}, 2^{1.41}, 2^{1.414}, \\dots$\uc640 \uac19\uc740 \uac12\ub4e4\uc744 \ucc28\ub840\ub85c \uacc4\uc0b0\ud558\uba74 \ud558\ub098\uc758 \uc77c\uc815\ud55c \uac12\uc73c\ub85c \uc218\ub834\ud558\uac8c \ub418\ub294\ub370, \uc774 \uac12\uc744 $2^{\\sqrt{2}}$\ub85c \uc815\uc758\ud558\ub294 \uac83\uc785\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uc2e4\uc218\uc9c0\uc218\ub294 \uc9c0\uc218\ud568\uc218\uc758 \uc5f0\uc18d\uc131\uc744 \ubcf4\uc7a5\ud558\uba70, \uc218\ud559\uc801 \ubaa8\ub378\ub9c1\uc5d0\uc11c \uc131\uc7a5\uacfc \uac10\uc1e0\ub97c \ub2e4\ub8f0 \ub54c \ud544\uc218\uc801\uc778 \uac1c\ub150\uc785\ub2c8\ub2e4.","\uc608\uc81c: \ub2e4\uc74c \uc2dd\uc744 \uac04\ub2e8\ud788 \ud558\uc2dc\uc624. $(3^{\\sqrt{2}})^{\\sqrt{8}} \\div 3^2$. \uc774 \ubb38\uc81c\ub97c \ud480\uae30 \uc704\ud574\uc11c\ub294 \uc9c0\uc218\ubc95\uce59 $(a^x)^y = a^{xy}$\uc640 $a^x \\div a^y = a^{x-y}$\ub97c \uc21c\ucc28\uc801\uc73c\ub85c \uc801\uc6a9\ud574\uc57c \ud569\ub2c8\ub2e4. \uba3c\uc800 \uad04\ud638 \uc548\uc758 \uc9c0\uc218\ub97c \uacc4\uc0b0\ud558\uba74 $\\sqrt{2} \\times \\sqrt{8} = \\sqrt{16} = 4$\uac00 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc2dd\uc740 $3^4 \\div 3^2$\uc774 \ub429\ub2c8\ub2e4.","\ub2e8\uacc4\ubcc4 \ud480\uc774\ub97c \uc9c4\ud589\ud558\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uccab\uc9f8, $(3^{\\sqrt{2}})^{\\sqrt{8}} = 3^{\\sqrt{2} \\times \\sqrt{8}} = 3^{\\sqrt{16}} = 3^4$\uc785\ub2c8\ub2e4. \ub458\uc9f8, \uc774\ub97c \ub098\ub217\uc148 \uc2dd\uc5d0 \ub300\uc785\ud558\uba74 $3^4 \\div 3^2$\uc774 \ub429\ub2c8\ub2e4. \uc14b\uc9f8, \uc9c0\uc218\ubc95\uce59 $a^x \\div a^y = a^{x-y}$\uc5d0 \uc758\ud574 $3^{4-2} = 3^2$\uc774 \ub429\ub2c8\ub2e4. \ucd5c\uc885\uc801\uc73c\ub85c $3^2 = 9$\ub77c\ub294 \uac12\uc744 \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),ag5,B.p)],ai2),ag5,B.p)],ai3),s3,s3,s3,"concept_\uc2e4\uc218\uc9c0\uc218",0,"","\ub300\uc218 > \uc9c0\uc218 > \uc9c0\uc218\uc758\ud655\uc7a5 > \uc2e4\uc218\uc9c0\uc218",p9,ag5,s3)
q0=A.a(["\uacf5\ud1b5\uc218\ud5592","\uba85\uc81c","\uba85\uc81c\uc758\uc5ed\uacfc\ub300\uc6b0","\ub300\uc6b0"],ai0)
q0=A.av(s2,A.a([A.au(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uba85\uc81c > \uba85\uc81c\uc758\uc5ed\uacfc\ub300\uc6b0 > \ub300\uc6b0 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.r,A.a(["\uba85\uc81c '\uc774\uba74 $p$\uc774\uba74 $q$\uc774\ub2e4'\ub97c \uae30\ud638\ub85c $p \\implies q$\ub77c\uace0 \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uac00\uc815\uc778 $p$\uc640 \uacb0\ub860\uc778 $q$\uc758 \uc704\uce58\ub97c \ubc14\uafb8\uace0, \uac01\uac01\uc744 \ubd80\uc815\ud558\uc5ec '\uc774\uba74 $q$\uac00 \uc544\ub2c8\uba74 $p$\uac00 \uc544\ub2c8\ub2e4'\ub85c \ub9cc\ub4e0 \uba85\uc81c\ub97c \uc6d0\ub798 \uba85\uc81c\uc758 '\ub300\uc6b0'\ub77c\uace0 \ud569\ub2c8\ub2e4. \uc774\ub97c \uae30\ud638\ub85c \ub098\ud0c0\ub0b4\uba74 $\\neg q \\implies \\neg p$\uac00 \ub429\ub2c8\ub2e4. \ub300\uc6b0\ub294 \uba85\uc81c\uc640 \ub9e4\uc6b0 \ud2b9\ubcc4\ud55c \uad00\uacc4\ub97c \ub9fa\uace0 \uc788\ub294\ub370, \uc6d0\ub798 \uba85\uc81c\uac00 \ucc38\uc774\uba74 \uadf8 \ub300\uc6b0\ub3c4 \ubc18\ub4dc\uc2dc \ucc38\uc774\uace0, \uc6d0\ub798 \uba85\uc81c\uac00 \uac70\uc9d3\uc774\uba74 \uadf8 \ub300\uc6b0\ub3c4 \ubc18\ub4dc\uc2dc \uac70\uc9d3\uc774\ub77c\ub294 \uc131\uc9c8\uc774 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\ub7ec\ud55c \uc131\uc9c8\uc774 \uc911\uc694\ud55c \uc774\uc720\ub294 \uc5b4\ub5a4 \uba85\uc81c\uc758 \ucc38\uacfc \uac70\uc9d3\uc744 \ud310\ubcc4\ud558\uae30 \uc5b4\ub824\uc6b8 \ub54c, \uadf8 \ub300\uc6b0\ub97c \uc774\uc6a9\ud558\uba74 \ud6e8\uc52c \uc27d\uac8c \ud574\uacb0\ud560 \uc218 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, '\uc5b4\ub5a4 \uc870\uac74\uc774 \ubcf5\uc7a1\ud558\uac8c \uc5bd\ud600 \uc788\uc5b4 \uc9c1\uc811 \uc99d\uba85\ud558\uae30 \ud798\ub4e4 \ub54c' \uadf8 \ub300\uc6b0\ub97c \uad6c\ud558\uc5ec \uc99d\uba85\ud558\uba74 \ub17c\ub9ac\uc801\uc73c\ub85c \uc644\ubcbd\ud558\uac8c \uc6d0\ub798 \uba85\uc81c\uc758 \ucc38, \uac70\uc9d3\uc744 \ubc1d\ud600\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc218\ud559\uc5d0\uc11c \ub300\uc6b0\ub294 \ubcf5\uc7a1\ud55c \ubb38\uc81c\ub97c \ub2e8\uc21c\ud55c \ubb38\uc81c\ub85c \ubc14\uafb8\uc5b4 \ud574\uacb0\ud558\ub294 \uac15\ub825\ud55c \ub3c4\uad6c\ub85c \uc0ac\uc6a9\ub429\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud1b5\ud574 \ub300\uc6b0\ub97c \uad6c\ud558\ub294 \ubc29\ubc95\uc744 \uc54c\uc544\ubd05\uc2dc\ub2e4. \uba85\uc81c '$x$\uac00 \ud640\uc218\uc774\uba74 $x^2$\uc740 \ud640\uc218\uc774\ub2e4'\ub77c\ub294 \ubb38\uc7a5\uc774 \uc788\uc744 \ub54c, \uc774 \uba85\uc81c\uc758 \ub300\uc6b0\ub97c \uad6c\ud574\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uac00\uc815\uc778 '$x$\uac00 \ud640\uc218\uc774\ub2e4'\uc758 \ubd80\uc815\uc740 '$x$\uac00 \uc9dd\uc218\uc774\ub2e4'\uac00 \ub418\uace0, \uacb0\ub860\uc778 '$x^2$\uc740 \ud640\uc218\uc774\ub2e4'\uc758 \ubd80\uc815\uc740 '$x^2$\uc740 \uc9dd\uc218\uc774\ub2e4'\uac00 \ub429\ub2c8\ub2e4. \uc774\uc81c \uac00\uc815\uacfc \uacb0\ub860\uc758 \uc704\uce58\ub97c \ubc14\uafb8\uc5b4 \uc5f0\uacb0\ud558\uba74 \ub300\uc6b0\ub294 '$x^2$\uc774 \uc9dd\uc218\uc774\uba74 $x$\ub294 \uc9dd\uc218\uc774\ub2e4'\uac00 \ub429\ub2c8\ub2e4.","\ub610 \ub2e4\ub978 \uc608\uc81c\ub85c, '\ub450 \uc2e4\uc218 $a, b$\uc5d0 \ub300\ud558\uc5ec $a+b > 2$\uc774\uba74 $a > 1$ \ub610\ub294 $b > 1$\uc774\ub2e4'\ub77c\ub294 \uba85\uc81c\uc758 \ub300\uc6b0\ub97c \uad6c\ud574\ubd05\uc2dc\ub2e4. \uc5ec\uae30\uc11c '\ub610\ub294'\uc758 \ubd80\uc815\uc740 '\uadf8\ub9ac\uace0'\uac00 \ub428\uc744 \uc8fc\uc758\ud574\uc57c \ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c \uac00\uc815\uacfc \uacb0\ub860\uc758 \uc704\uce58\ub97c \ubc14\uafb8\uace0 \uac01\uac01\uc744 \ubd80\uc815\ud558\uba74, \ub300\uc6b0\ub294 '$a \\le 1$\uc774\uace0 $b \\le 1$\uc774\uba74 $a+b \\le 2$\uc774\ub2e4'\uac00 \ub429\ub2c8\ub2e4. \uc774\ucc98\ub7fc \ub300\uc6b0\ub97c \uad6c\ud560 \ub54c\ub294 '\uadf8\ub9ac\uace0'\uc640 '\ub610\ub294'\uc758 \uad00\uacc4\uac00 \uc11c\ub85c \ubc14\ub010\ub2e4\ub294 \uc810\uc744 \ud56d\uc0c1 \uae30\uc5b5\ud574\uc57c \ud569\ub2c8\ub2e4.","\ub9c8\uc9c0\ub9c9\uc73c\ub85c \ub300\uc6b0\ub97c \uc774\uc6a9\ud55c \uc99d\uba85 \ubb38\uc81c\ub97c \ud480\uc5b4\ubd05\uc2dc\ub2e4. '\uc790\uc5f0\uc218 $n$\uc5d0 \ub300\ud558\uc5ec $n^2$\uc774 3\uc758 \ubc30\uc218\uc774\uba74 $n$\ub3c4 3\uc758 \ubc30\uc218\uc774\ub2e4'\ub77c\ub294 \uba85\uc81c\ub97c \uc99d\uba85\ud558\uae30 \uc704\ud574 \ub300\uc6b0\ub97c \uc774\uc6a9\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uc774 \uba85\uc81c\uc758 \ub300\uc6b0\ub294 '$n$\uc774 3\uc758 \ubc30\uc218\uac00 \uc544\ub2c8\uba74 $n^2$\ub3c4 3\uc758 \ubc30\uc218\uac00 \uc544\ub2c8\ub2e4'\uc785\ub2c8\ub2e4. $n$\uc774 3\uc758 \ubc30\uc218\uac00 \uc544\ub2c8\uba74 $n$\uc740 $3k+1$ \ub610\ub294 $3k+2$ (\ub2e8, $k$\ub294 0 \uc774\uc0c1\uc758 \uc815\uc218) \uaf34\ub85c \ub098\ud0c0\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uccab\uc9f8, $n = 3k+1$\uc77c \ub54c $n^2 = (3k+1)^2 = 9k^2 + 6k + 1 = 3(3k^2 + 2k) + 1$\uc774 \ub418\uc5b4 3\uc758 \ubc30\uc218\uac00 \uc544\ub2d9\ub2c8\ub2e4. \ub458\uc9f8, $n = 3k+2$\uc77c \ub54c $n^2 = (3k+2)^2 = 9k^2 + 12k + 4 = 3(3k^2 + 4k + 1) + 1$\uc774 \ub418\uc5b4 \uc5ed\uc2dc 3\uc758 \ubc30\uc218\uac00 \uc544\ub2d9\ub2c8\ub2e4. \ub300\uc6b0\uac00 \ucc38\uc784\uc744 \ud655\uc778\ud588\uc73c\ubbc0\ub85c, \uc6d0\ub798 \uba85\uc81c\uc778 '$n^2$\uc774 3\uc758 \ubc30\uc218\uc774\uba74 $n$\ub3c4 3\uc758 \ubc30\uc218\uc774\ub2e4'\ub3c4 \ucc38\uc774\ub77c\ub294 \uacb0\ub860\uc744 \ub0b4\ub9b4 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),"\ub300\uc6b0",B.p)],ai2),"\ub300\uc6b0",B.p)],ai3),s3,s3,s3,"concept_\ub300\uc6b0",0,"","\uacf5\ud1b5\uc218\ud5592 > \uba85\uc81c > \uba85\uc81c\uc758\uc5ed\uacfc\ub300\uc6b0 > \ub300\uc6b0",q0,"\ub300\uc6b0",s3)
q1=A.a(["\uacf5\ud1b5\uc218\ud5591","\ub2e4\ud56d\uc2dd","\ub098\uba38\uc9c0\uc815\ub9ac","\ub098\uba38\uc9c0\uc815\ub9ac\uc99d\uba85"],ai0)
q1=A.av(s2,A.a([A.au(A.a(["\uacf5\ud1b5\uc218\ud5591 > \ub2e4\ud56d\uc2dd > \ub098\uba38\uc9c0\uc815\ub9ac > \ub098\uba38\uc9c0\uc815\ub9ac\uc99d\uba85 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.r,A.a(["\ub098\uba38\uc9c0\uc815\ub9ac\ub780 \ub2e4\ud56d\uc2dd $P(x)$\ub97c \uc77c\ucc28\uc2dd $x-a$\ub85c \ub098\ub204\uc5c8\uc744 \ub54c\uc758 \ub098\uba38\uc9c0\ub97c \uc9c1\uc811 \ub098\ub217\uc148\uc744 \ud558\uc9c0 \uc54a\uace0\ub3c4 \uac04\ub2e8\ud788 \uad6c\ud560 \uc218 \uc788\ub294 \uc815\ub9ac\uc785\ub2c8\ub2e4. \ub2e4\ud56d\uc2dd $P(x)$\ub97c $x-a$\ub85c \ub098\ub204\uc5c8\uc744 \ub54c\uc758 \ubaab\uc744 $Q(x)$, \ub098\uba38\uc9c0\ub97c $R$\uc774\ub77c\uace0 \ud558\uba74, \ub098\ub217\uc148\uc758 \uc6d0\ub9ac\uc5d0 \uc758\ud574 $P(x) = (x-a)Q(x) + R$\uc774\ub77c\ub294 \ud56d\ub4f1\uc2dd\uc774 \uc131\ub9bd\ud569\ub2c8\ub2e4. \uc774\ub54c \ub098\uba38\uc9c0\ub294 \ub098\ub204\ub294 \uc2dd\uc758 \ucc28\uc218\ubcf4\ub2e4 \ub0ae\uc544\uc57c \ud558\ubbc0\ub85c, \uc77c\ucc28\uc2dd\uc73c\ub85c \ub098\ub204\uc5c8\uc744 \ub54c\uc758 \ub098\uba38\uc9c0 $R$\uc740 \uc0c1\uc218\ud56d\uc774 \ub429\ub2c8\ub2e4.","\uc774 \ud56d\ub4f1\uc2dd\uc5d0\uc11c $x$\uc5d0 \uc5b4\ub5a4 \uac12\uc744 \ub300\uc785\ud574\ub3c4 \ub4f1\uc2dd\uc740 \ud56d\uc0c1 \uc131\ub9bd\ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c $x$ \ub300\uc2e0 $a$\ub97c \ub300\uc785\ud558\uba74 $P(a) = (a-a)Q(a) + R$\uc774 \ub429\ub2c8\ub2e4. \uc5ec\uae30\uc11c $(a-a)$\ub294 $0$\uc774\ubbc0\ub85c $0 \\cdot Q(a)$\ub294 \uc0ac\ub77c\uc9c0\uace0, \uacb0\uacfc\uc801\uc73c\ub85c $P(a) = R$\uc774\ub77c\ub294 \uacb0\ub860\uc744 \uc5bb\uac8c \ub429\ub2c8\ub2e4. \uc989, \ub2e4\ud56d\uc2dd $P(x)$\ub97c $x-a$\ub85c \ub098\ub208 \ub098\uba38\uc9c0\ub294 \ub2e4\ud56d\uc2dd\uc5d0 $x=a$\ub97c \ub300\uc785\ud55c \uac12\uc778 $P(a)$\uc640 \uac19\uc2b5\ub2c8\ub2e4.","\uc774 \uc131\uc9c8\uc744 \ud655\uc7a5\ud558\uba74 $P(x)$\ub97c $ax+b$ \uaf34\uc758 \uc77c\ucc28\uc2dd\uc73c\ub85c \ub098\ub20c \ub54c\ub3c4 \uc801\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. $P(x) = (ax+b)Q(x) + R$\uc5d0\uc11c $ax+b=0$\uc774 \ub418\ub294 $x$\uac12\uc778 $-\\frac{b}{a}$\ub97c \ub300\uc785\ud558\uba74, $P(-\\frac{b}{a}) = (a \\cdot (-\\frac{b}{a}) + b)Q(-\\frac{b}{a}) + R$\uc774 \ub418\uc5b4 \uacb0\uad6d $P(-\\frac{b}{a}) = R$\uc774 \uc131\ub9bd\ud568\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uc608\uc81c\ub97c \ud1b5\ud574 \uc9c1\uc811 \uc801\uc6a9\ud574 \ubd05\uc2dc\ub2e4. \ub2e4\ud56d\uc2dd $P(x) = 2x^3 - 3x^2 + x + 5$\ub97c $x-2$\ub85c \ub098\ub204\uc5c8\uc744 \ub54c\uc758 \ub098\uba38\uc9c0\ub97c \uad6c\ud558\ub294 \ubb38\uc81c\uc785\ub2c8\ub2e4. \ub098\uba38\uc9c0\uc815\ub9ac\uc5d0 \ub530\ub974\uba74 \ub098\uba38\uc9c0\ub294 $P(2)$\uc758 \uac12\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uba3c\uc800 $x$ \uc790\ub9ac\uc5d0 $2$\ub97c \ub300\uc785\ud558\uc5ec \uc2dd\uc744 \uc138\uc6c1\ub2c8\ub2e4. $P(2) = 2(2)^3 - 3(2)^2 + 2 + 5$.","\ub2e8\uacc4\ubcc4\ub85c \uacc4\uc0b0\ud558\uba74, $2^3 = 8$\uc774\ubbc0\ub85c $2 \\times 8 = 16$\uc774\uace0, $2^2 = 4$\uc774\ubbc0\ub85c $3 \\times 4 = 12$\uac00 \ub429\ub2c8\ub2e4. \uc774\ub97c \uc2dd\uc5d0 \ub300\uc785\ud558\uba74 $P(2) = 16 - 12 + 2 + 5$\uac00 \ub429\ub2c8\ub2e4. \uc774\ub97c \ucc28\ub840\ub300\ub85c \uacc4\uc0b0\ud558\uba74 $16 - 12 = 4$\uc774\uace0, $4 + 2 + 5 = 11$\uc774 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \ub2e4\ud56d\uc2dd $P(x)$\ub97c $x-2$\ub85c \ub098\ub208 \ub098\uba38\uc9c0\ub294 $11$\uc785\ub2c8\ub2e4."],ai0),ag6,B.p)],ai2),ag6,B.p)],ai3),s3,s3,s3,"concept_\ub098\uba38\uc9c0\uc815\ub9ac\uc99d\uba85",0,"","\uacf5\ud1b5\uc218\ud5591 > \ub2e4\ud56d\uc2dd > \ub098\uba38\uc9c0\uc815\ub9ac > \ub098\uba38\uc9c0\uc815\ub9ac\uc99d\uba85",q1,ag6,s3)
q2=A.a(["\ub300\uc218","\uc218\uc5f4","\ud569\uc758\uae30\ud638\uc2dc\uadf8\ub9c8","\uc2dc\uadf8\ub9c8\uc758\uc131\uc9c8"],ai0)
q2=A.av(s2,A.a([A.au(A.a(["\ub300\uc218 > \uc218\uc5f4 > \ud569\uc758\uae30\ud638\uc2dc\uadf8\ub9c8 > \uc2dc\uadf8\ub9c8\uc758\uc131\uc9c8 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.r,A.a(["\uc218\uc5f4\uc758 \ud569\uc744 \ub098\ud0c0\ub0b4\ub294 \uae30\ud638\uc778 \uc2dc\uadf8\ub9c8($\\sum$)\ub294 \ubcf5\uc7a1\ud55c \uc218\uc5f4\uc758 \ud569\uc744 \uac04\uacb0\ud558\uac8c \ud45c\ud604\ud558\uae30 \uc704\ud574 \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \uc2dc\uadf8\ub9c8\uc758 \uc131\uc9c8\uc744 \uc774\ud574\ud558\uba74 \uc218\uc5f4\uc758 \ud569\uc744 \uacc4\uc0b0\ud560 \ub54c \uc77c\uc77c\uc774 \ub098\uc5f4\ud558\uc9c0 \uc54a\uace0\ub3c4 \ud6a8\uc728\uc801\uc73c\ub85c \uac12\uc744 \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uac00\uc7a5 \uae30\ubcf8\uc801\uc778 \uc131\uc9c8\uc740 \ud569\uc758 \uae30\ud638 \uc548\uc5d0\uc11c \uc0c1\uc218\ubc30\uac00 \ub418\uc5b4 \uc788\ub294 \uacbd\uc6b0 \uc0c1\uc218\ub97c \uae30\ud638 \uc55e\uc73c\ub85c \ub044\uc9d1\uc5b4\ub0bc \uc218 \uc788\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4. \uc989, \uc0c1\uc218 $c$\uc5d0 \ub300\ud558\uc5ec $$\\sum_{k=1}^{n} c a_k = c \\sum_{k=1}^{n} a_k$$ \uac00 \uc131\ub9bd\ud569\ub2c8\ub2e4.","\ub610\ud55c, \uc2dc\uadf8\ub9c8\ub294 \ub367\uc148\uacfc \ube84\uc148\uc5d0 \ub300\ud574 \uac01\uac01 \ubd84\ubc30\uac00 \uac00\ub2a5\ud558\ub2e4\ub294 \uc911\uc694\ud55c \uc131\uc9c8\uc744 \uac00\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ub450 \uc218\uc5f4 $a_k$\uc640 $b_k$\uc5d0 \ub300\ud558\uc5ec \ud569\uacfc \ucc28\uc758 \uc2dc\uadf8\ub9c8\ub294 \uac01\uac01\uc758 \uc2dc\uadf8\ub9c8\ub97c \ub354\ud558\uac70\ub098 \ube80 \uac83\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uc774\ub97c \uc2dd\uc73c\ub85c \ub098\ud0c0\ub0b4\uba74 $$\\sum_{k=1}^{n} (a_k + b_k) = \\sum_{k=1}^{n} a_k + \\sum_{k=1}^{n} b_k$$ \uc774\uace0, $$\\sum_{k=1}^{n} (a_k - b_k) = \\sum_{k=1}^{n} a_k - \\sum_{k=1}^{n} b_k$$ \uc785\ub2c8\ub2e4. \ub2e4\ub9cc, \uacf1\uc148\uc774\ub098 \ub098\ub217\uc148\uc5d0 \ub300\ud574\uc11c\ub294 \uc774\ub7ec\ud55c \ubd84\ubc30 \ubc95\uce59\uc774 \uc131\ub9bd\ud558\uc9c0 \uc54a\uc73c\ubbc0\ub85c \uc8fc\uc758\ud574\uc57c \ud569\ub2c8\ub2e4.","\ub9c8\uc9c0\ub9c9\uc73c\ub85c, \uc2dc\uadf8\ub9c8 \uae30\ud638 \uc548\uc758 \uac12\uc774 \uc0c1\uc218\uc778 \uacbd\uc6b0\uc758 \uc131\uc9c8\uc785\ub2c8\ub2e4. \ub9cc\uc57d $k$\uac12\uc5d0 \uad00\uacc4\uc5c6\uc774 \ud56d\uc0c1 \uc77c\uc815\ud55c \uc0c1\uc218 $c$\ub97c $n$\ubc88 \ub354\ud55c\ub2e4\uba74, \uadf8 \uacb0\uacfc\ub294 \uc0c1\uc218 $c$\uc5d0 \ud56d\uc758 \uac1c\uc218\uc778 $n$\uc744 \uacf1\ud55c \uac83\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uc989, $$\\sum_{k=1}^{n} c = nc$$ \ub77c\ub294 \uacf5\uc2dd\uc774 \uc131\ub9bd\ud569\ub2c8\ub2e4. \uc774 \uc138 \uac00\uc9c0 \uc131\uc9c8(\uc0c1\uc218\ubc30, \ub367\uc148\xb7\ube84\uc148\uc758 \ubd84\ubc30, \uc0c1\uc218\ud56d\uc758 \ud569)\uc744 \uc801\uc808\ud788 \uc870\ud569\ud558\uba74 \uc5b4\ub5a4 \ub2e4\ud56d\uc2dd \ud615\ud0dc\uc758 \uc218\uc5f4 \ud569\uc774\ub77c\ub3c4 \uc27d\uac8c \uacc4\uc0b0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uc608\uc81c\ub97c \ud1b5\ud574 \uc2dc\uadf8\ub9c8\uc758 \uc131\uc9c8\uc744 \uc801\uc6a9\ud574 \ubd05\uc2dc\ub2e4. \ubb38\uc81c: $\\sum_{k=1}^{10} (3k + 2)$\uc758 \uac12\uc744 \uad6c\ud558\uc2dc\uc624. \uba3c\uc800 \uc2dc\uadf8\ub9c8\uc758 \ub367\uc148 \uc131\uc9c8\uc744 \uc774\uc6a9\ud558\uc5ec \uc2dd\uc744 \ubd84\ub9ac\ud569\ub2c8\ub2e4. $$\\sum_{k=1}^{10} (3k + 2) = \\sum_{k=1}^{10} 3k + \\sum_{k=1}^{10} 2$$ \ub85c \ub098\ub20c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uccab \ubc88\uc9f8 \ud56d\uc740 \uc0c1\uc218\ubc30 \uc131\uc9c8\uc744 \uc774\uc6a9\ud574 $3 \\sum_{k=1}^{10} k$\ub85c \ubcc0\ud615\ud569\ub2c8\ub2e4.","\uc774\uc81c \uac01 \ubd80\ubd84\uc744 \uacc4\uc0b0\ud569\ub2c8\ub2e4. \uc790\uc5f0\uc218\uc758 \ud569 \uacf5\uc2dd $\\sum_{k=1}^{n} k = \\frac{n(n+1)}{2}$\uc744 \uc774\uc6a9\ud558\uba74, $3 \\sum_{k=1}^{10} k = 3 \\times \\frac{10 \\times 11}{2} = 3 \\times 55 = 165$\uac00 \ub429\ub2c8\ub2e4. \ub610\ud55c \uc0c1\uc218\ud56d\uc758 \uc131\uc9c8\uc5d0 \uc758\ud574 $\\sum_{k=1}^{10} 2 = 2 \\times 10 = 20$\uc774 \ub429\ub2c8\ub2e4. \ucd5c\uc885\uc801\uc73c\ub85c \ub450 \uac12\uc744 \ub354\ud558\uba74 $165 + 20 = 185$\ub77c\ub294 \uacb0\uacfc\ub97c \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),ag7,B.p)],ai2),ag7,B.p)],ai3),s3,s3,s3,"concept_\uc2dc\uadf8\ub9c8\uc758\uc131\uc9c8",0,"","\ub300\uc218 > \uc218\uc5f4 > \ud569\uc758\uae30\ud638\uc2dc\uadf8\ub9c8 > \uc2dc\uadf8\ub9c8\uc758\uc131\uc9c8",q2,ag7,s3)
q3=A.a(["\uacf5\ud1b5\uc218\ud5592","\uc88c\ud45c\ud3c9\uba74","\uc120\ubd84\uc758\ub0b4\ubd84\uc810","\uc911\uc810"],ai0)
q3=A.av(s2,A.a([A.au(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \uc120\ubd84\uc758\ub0b4\ubd84\uc810 > \uc911\uc810 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.r,A.a(["\uc88c\ud45c\ud3c9\uba74 \uc704\uc758 \ub450 \uc810 $A(x_1, y_1)$\uacfc $B(x_2, y_2)$\ub97c \uc787\ub294 \uc120\ubd84 $AB$\uac00 \uc788\uc744 \ub54c, \uc774 \uc120\ubd84\uc744 \ub611\uac19\uc740 \uae38\uc774\ub85c \uc774\ub4f1\ubd84\ud558\ub294 \uc810\uc744 '\uc911\uc810'\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4. \uc911\uc810\uc740 \uc120\ubd84\uc758 \uc591 \ub05d\uc810\uc73c\ub85c\ubd80\ud130 \uac19\uc740 \uac70\ub9ac\uc5d0 \uc704\uce58\ud558\uba70, \uae30\ud558\ud559\uc801\uc73c\ub85c\ub294 \uc120\ubd84\uc758 \ubb34\uac8c\uc911\uc2ec\uacfc \uac19\uc740 \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4. \uc911\uc810\uc758 \uc88c\ud45c\ub97c \uad6c\ud558\ub294 \uac83\uc740 \uc120\ubd84\uc744 $1:1$\uc758 \ube44\uc728\ub85c \ub0b4\ubd84\ud558\ub294 \uc810\uc744 \ucc3e\ub294 \uac83\uacfc \ub3d9\uc77c\ud55c \uc6d0\ub9ac\uc785\ub2c8\ub2e4.","\uc911\uc810\uc758 \uc88c\ud45c\ub97c \uad6c\ud558\ub294 \uacf5\uc2dd\uc740 \ub9e4\uc6b0 \uc9c1\uad00\uc801\uc785\ub2c8\ub2e4. \ub450 \uc810\uc758 $x$\uc88c\ud45c\ub07c\ub9ac \ub354\ud574\uc11c $2$\ub85c \ub098\ub204\uace0, $y$\uc88c\ud45c\ub07c\ub9ac \ub354\ud574\uc11c $2$\ub85c \ub098\ub204\uba74 \ub429\ub2c8\ub2e4. \uc989, \uc120\ubd84 $AB$\uc758 \uc911\uc810 $M(x, y)$\uc758 \uc88c\ud45c\ub294 \ub2e4\uc74c\uacfc \uac19\uc774 \uc815\uc758\ub429\ub2c8\ub2e4. $$M = \\left( \\frac{x_1 + x_2}{2}, \\frac{y_1 + y_2}{2} \\right)$$ \uc774 \uacf5\uc2dd\uc740 \uc218\uc9c1\uc120 \uc704\uc5d0\uc11c \ub450 \uc810\uc758 \ud3c9\uade0\uc744 \uad6c\ud558\ub294 \uac83\uacfc \uac19\uc740 \ub17c\ub9ac\uc774\uba70, \uc88c\ud45c\ud3c9\uba74\uc5d0\uc11c\ub294 $x$\ucd95\uacfc $y$\ucd95\uc5d0 \ub300\ud574 \uac01\uac01 \ud3c9\uade0\uc744 \uad6c\ud558\ub294 \uac83\uc73c\ub85c \uc774\ud574\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc608\ub97c \ub4e4\uc5b4, \uc88c\ud45c\ud3c9\uba74 \uc704\uc758 \ub450 \uc810 $A(2, 4)$\uc640 $B(6, 8)$\uc744 \uc787\ub294 \uc120\ubd84 $AB$\uc758 \uc911\uc810 $M$\uc744 \uad6c\ud558\ub294 \uacfc\uc815\uc744 \uc0b4\ud3b4\ubd05\uc2dc\ub2e4. \uc911\uc810\uc758 $x$\uc88c\ud45c\ub294 \ub450 \uc810\uc758 $x$\uc88c\ud45c\uc778 $2$\uc640 $6$\uc758 \ud3c9\uade0\uc774\ubbc0\ub85c $\\frac{2+6}{2} = 4$\uac00 \ub429\ub2c8\ub2e4. \ub9c8\ucc2c\uac00\uc9c0\ub85c $y$\uc88c\ud45c\ub294 \ub450 \uc810\uc758 $y$\uc88c\ud45c\uc778 $4$\uc640 $8$\uc758 \ud3c9\uade0\uc774\ubbc0\ub85c $\\frac{4+8}{2} = 6$\uc774 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uad6c\ud558\ub294 \uc911\uc810 $M$\uc758 \uc88c\ud45c\ub294 $(4, 6)$\uc785\ub2c8\ub2e4.","\uc870\uae08 \ub354 \ubcf5\uc7a1\ud55c \uc608\uc81c\ub85c, \uc810 $A(-3, 5)$\uc640 \uc810 $B(5, -1)$\uc744 \uc787\ub294 \uc120\ubd84 $AB$\uc758 \uc911\uc810 $M$\uc744 \uad6c\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uacf5\uc2dd\uc5d0 \ub530\ub77c $x$\uc88c\ud45c\uc640 $y$\uc88c\ud45c\ub97c \uac01\uac01 \uacc4\uc0b0\ud558\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uba3c\uc800 $x$\uc88c\ud45c\ub294 $x = \\frac{-3 + 5}{2} = \\frac{2}{2} = 1$\uc785\ub2c8\ub2e4. \ub2e4\uc74c\uc73c\ub85c $y$\uc88c\ud45c\ub294 $y = \\frac{5 + (-1)}{2} = \\frac{4}{2} = 2$\uc785\ub2c8\ub2e4. \uacb0\uacfc\uc801\uc73c\ub85c \uc911\uc810 $M$\uc758 \uc88c\ud45c\ub294 $(1, 2)$\uac00 \ub429\ub2c8\ub2e4.","\ub9c8\uc9c0\ub9c9\uc73c\ub85c, \uc911\uc810\uc758 \uc131\uc9c8\uc744 \ud65c\uc6a9\ud558\uc5ec \ubbf8\uc9c0\uc218\ub97c \uad6c\ud558\ub294 \ubb38\uc81c\ub97c \ud480\uc5b4\ubd05\uc2dc\ub2e4. \uc120\ubd84 $AB$\uc758 \uc911\uc810\uc774 $M(3, 2)$\uc774\uace0, \uc810 $A$\uc758 \uc88c\ud45c\uac00 $(1, 5)$\uc77c \ub54c, \uc810 $B(x, y)$\uc758 \uc88c\ud45c\ub97c \uad6c\ud558\ub294 \ubb38\uc81c\uc785\ub2c8\ub2e4. \uc911\uc810 \uacf5\uc2dd\uc5d0 \uc758\ud574 $\\frac{1+x}{2} = 3$\uc774\uace0 $\\frac{5+y}{2} = 2$\uac00 \uc131\ub9bd\ud569\ub2c8\ub2e4. \uccab \ubc88\uc9f8 \uc2dd\uc5d0\uc11c $1+x = 6$\uc774 \ub418\uc5b4 $x = 5$\ub97c \uc5bb\uace0, \ub450 \ubc88\uc9f8 \uc2dd\uc5d0\uc11c $5+y = 4$\uac00 \ub418\uc5b4 $y = -1$\uc744 \uc5bb\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc810 $B$\uc758 \uc88c\ud45c\ub294 $(5, -1)$\uc785\ub2c8\ub2e4."],ai0),"\uc911\uc810",B.p)],ai2),"\uc911\uc810",B.p)],ai3),s3,s3,s3,"concept_\uc911\uc810",0,"","\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \uc120\ubd84\uc758\ub0b4\ubd84\uc810 > \uc911\uc810",q3,"\uc911\uc810",s3)
q4=A.a(["\ub300\uc218","\uc9c0\uc218","\uc9c0\uc218\ubc95\uce59","\uc9c0\uc218\ubc95\uce59\uc758\uc131\uc9c8"],ai0)
q4=A.av(s2,A.a([A.au(A.a(["\ub300\uc218 > \uc9c0\uc218 > \uc9c0\uc218\ubc95\uce59 > \uc9c0\uc218\ubc95\uce59\uc758\uc131\uc9c8 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.r,A.a(["\uc9c0\uc218\ubc95\uce59\uc774\ub780 \uac70\ub4ed\uc81c\uacf1\uc758 \uacc4\uc0b0\uc744 \uac04\ud3b8\ud558\uac8c \ud558\uae30 \uc704\ud574 \ub9cc\ub4e4\uc5b4\uc9c4 \uc218\ud559\uc801 \uc57d\uc18d\uc785\ub2c8\ub2e4. \uc5b4\ub5a4 \uc218 $a$\ub97c $n$\ubc88 \uacf1\ud55c \uac83\uc744 $a^n$\uc774\ub77c \uc4f0\uace0, \uc774\ub54c $a$\ub97c \ubc11, $n$\uc744 \uc9c0\uc218\ub77c\uace0 \ud569\ub2c8\ub2e4. \uc9c0\uc218\ubc95\uce59\uc758 \uac00\uc7a5 \uae30\ucd08\uac00 \ub418\ub294 \uc131\uc9c8\uc740 \ubc11\uc774 \uac19\uc740 \ub450 \uac70\ub4ed\uc81c\uacf1\uc744 \uacf1\ud560 \ub54c \uc9c0\uc218\ub07c\ub9ac \ub354\ud558\ub294 \uac83\uc785\ub2c8\ub2e4. \uc989, $a^m \\times a^n = a^{m+n}$\uc774 \uc131\ub9bd\ud569\ub2c8\ub2e4. \uc774\ub294 $a$\ub97c $m$\ubc88 \uacf1\ud55c \uac83\uc5d0 $a$\ub97c $n$\ubc88 \ub354 \uacf1\ud558\uba74 \ucd1d $a$\ub97c $m+n$\ubc88 \uacf1\ud558\uac8c \ub41c\ub2e4\ub294 \uc6d0\ub9ac\uc5d0\uc11c \ube44\ub86f\ub429\ub2c8\ub2e4.","\uc9c0\uc218\ubc95\uce59\uc5d0\ub294 \uacf1\uc148 \uc678\uc5d0\ub3c4 \ub098\ub217\uc148\uacfc \uac70\ub4ed\uc81c\uacf1\uc758 \uac70\ub4ed\uc81c\uacf1\uc5d0 \uad00\ud55c \uc131\uc9c8\uc774 \uc788\uc2b5\ub2c8\ub2e4. \ub098\ub217\uc148\uc758 \uacbd\uc6b0 $a^m \\div a^n = a^{m-n}$ ($m > n$\uc77c \ub54c)\uc774 \uc131\ub9bd\ud558\uba70, \uac70\ub4ed\uc81c\uacf1\uc758 \uac70\ub4ed\uc81c\uacf1\uc740 $(a^m)^n = a^{m \\times n}$\uc73c\ub85c \uacc4\uc0b0\ud569\ub2c8\ub2e4. \ub610\ud55c, \uad04\ud638 \uc548\uc758 \uacf1\uc148\uc774\ub098 \ub098\ub217\uc148\uc5d0 \uc9c0\uc218\uac00 \ubd99\uc5b4 \uc788\uc744 \ub54c\ub294 $(ab)^n = a^n b^n$ \ub610\ub294 $(\\frac{a}{b})^n = \\frac{a^n}{b^n}$\uacfc \uac19\uc774 \uc9c0\uc218\ub97c \uac01\uac01 \ubd84\ubc30\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc131\uc9c8\ub4e4\uc744 \uc775\ud788\uba74 \ubcf5\uc7a1\ud55c \uc2dd\uc744 \ub9e4\uc6b0 \uac04\ub2e8\ud558\uac8c \uc815\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud1b5\ud574 \uc9c0\uc218\ubc95\uce59\uc744 \uc801\uc6a9\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uccab \ubc88\uc9f8 \ubb38\uc81c\ub294 $2^3 \\times 2^4$\uc744 \uacc4\uc0b0\ud558\ub294 \uac83\uc785\ub2c8\ub2e4. \uc774 \uc2dd\uc740 \ubc11\uc774 2\ub85c \uac19\uc73c\ubbc0\ub85c \uc9c0\uc218\ubc95\uce59 $a^m \\times a^n = a^{m+n}$\uc744 \uc801\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c $2^3 \\times 2^4 = 2^{3+4} = 2^7$\uc774 \ub429\ub2c8\ub2e4. $2^7$\uc740 2\ub97c 7\ubc88 \uacf1\ud55c \uac12\uc778 128\uc774\ubbc0\ub85c, \ucd5c\uc885 \uacb0\uacfc\ub294 128\uc785\ub2c8\ub2e4.","\ub450 \ubc88\uc9f8 \uc608\uc81c\ub85c \uc2dd $(x^2 y^3)^4$\uc744 \uac04\ub2e8\ud788 \uc815\ub9ac\ud574 \ubd05\uc2dc\ub2e4. \uc774 \uc2dd\uc740 \uad04\ud638 \uc548\uc758 \uac01 \ud56d\uc5d0 \uc9c0\uc218 4\ub97c \ubd84\ubc30\ud558\ub294 \ubc95\uce59\uc778 $(a^m b^n)^p = a^{m \\times p} b^{n \\times p}$\ub97c \uc774\uc6a9\ud569\ub2c8\ub2e4. \uba3c\uc800 $x^2$\uc5d0 4\ub97c \uacf1\ud558\uc5ec $x^{2 \\times 4} = x^8$\uc774 \ub418\uace0, $y^3$\uc5d0 4\ub97c \uacf1\ud558\uc5ec $y^{3 \\times 4} = y^{12}$\uac00 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc2dd\uc744 \uc815\ub9ac\ud558\uba74 $x^8 y^{12}$\ub77c\ub294 \uacb0\uacfc\ub97c \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ub9c8\uc9c0\ub9c9\uc73c\ub85c \ub098\ub217\uc148\uc774 \ud3ec\ud568\ub41c \uc2dd $\\frac{3^6}{3^2}$\uc744 \uacc4\uc0b0\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uc9c0\uc218\ubc95\uce59 $a^m \\div a^n = a^{m-n}$\uc744 \uc801\uc6a9\ud558\uba74 \ubc11\uc774 3\uc77c \ub54c \uc9c0\uc218\ub07c\ub9ac \ube7c\uc8fc\uba74 \ub429\ub2c8\ub2e4. \uc989, $3^{6-2} = 3^4$\uc774 \ub429\ub2c8\ub2e4. $3^4$\uc740 $3 \\times 3 \\times 3 \\times 3$\uc744 \uc758\ubbf8\ud558\ubbc0\ub85c, $9 \\times 9 = 81$\uc774 \ucd5c\uc885 \uc815\ub2f5\uc785\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uc9c0\uc218\ubc95\uce59\uc744 \ud65c\uc6a9\ud558\uba74 \ud070 \uc218\ub97c \uc9c1\uc811 \uacf1\ud558\uc9c0 \uc54a\uace0\ub3c4 \ube60\ub974\uace0 \uc815\ud655\ud558\uac8c \uacc4\uc0b0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),ag8,B.p)],ai2),ag8,B.p)],ai3),s3,s3,s3,"concept_\uc9c0\uc218\ubc95\uce59\uc758\uc131\uc9c8",0,"","\ub300\uc218 > \uc9c0\uc218 > \uc9c0\uc218\ubc95\uce59 > \uc9c0\uc218\ubc95\uce59\uc758\uc131\uc9c8",q4,ag8,s3)
q5=A.a(["\ubbf8\uc801\ubd84\u2160","\ud568\uc218\uc758\uc99d\uac00\uc640\uac10\uc18c","\ub3c4\ud568\uc218\uc758\ubd80\ud638"],ai0)
q5=A.av(s2,A.a([A.au(A.a(["\ubbf8\uc801\ubd84\u2160 > \ud568\uc218\uc758\uc99d\uac00\uc640\uac10\uc18c > \ub3c4\ud568\uc218\uc758\ubd80\ud638 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.r,A.a(["[   \"\ud568\uc218\uc758 \uc99d\uac00\uc640 \uac10\uc18c\ub97c \ud310\ub2e8\ud560 \ub54c \uac00\uc7a5 \uac15\ub825\ud55c \ub3c4\uad6c\ub294 \ubc14\ub85c '\ub3c4\ud568\uc218\uc758 \ubd80\ud638'\uc785\ub2c8\ub2e4. \uc5b4\ub5a4 \uad6c\uac04\uc5d0\uc11c \ubbf8\ubd84\uac00\ub2a5\ud55c \ud568\uc218 $f(x)$\uac00 \uc788\uc744 \ub54c, \uadf8 \uad6c\uac04\uc758 \ubaa8\ub4e0 $x$\uc5d0 \ub300\ud558\uc5ec $f'(x) > 0$\uc774\uba74 \ud568\uc218 $f(x)$\ub294 \uadf8 \uad6c\uac04\uc5d0\uc11c \uc99d\uac00\ud569\ub2c8\ub2e4. \ubc18\ub300\ub85c $f'(x) < 0$\uc774\uba74 \ud568\uc218 $f(x)$\ub294 \uadf8 \uad6c\uac04\uc5d0\uc11c \uac10\uc18c\ud558\uac8c \ub429\ub2c8\ub2e4. \uc774\ub294 \ub3c4\ud568\uc218 $f'(x)$\uac00 \ud574\ub2f9 \uc9c0\uc810\uc5d0\uc11c\uc758 \uc811\uc120\uc758 \uae30\uc6b8\uae30\ub97c \uc758\ubbf8\ud558\uae30 \ub54c\ubb38\uc778\ub370, \uae30\uc6b8\uae30\uac00 \uc591\uc218\ub77c\ub294 \uac83\uc740 \uc624\ub978\ucabd \uc704\ub85c \ud5a5\ud558\ub294 \uadf8\ub798\ud504\ub97c, \uc74c\uc218\ub77c\ub294 \uac83\uc740 \uc624\ub978\ucabd \uc544\ub798\ub85c \ud5a5\ud558\ub294 \uadf8\ub798\ud504\ub97c \uadf8\ub9b0\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.\",   \"\uc870\uae08 \ub354 \uc5c4\ubc00\ud558\uac8c \ub9d0\ud558\uba74, \uad6c\uac04 \ub0b4\uc758 \ubaa8\ub4e0 $x$\uc5d0 \ub300\ud558\uc5ec $f'(x) \\geq 0$\uc774\uace0, \uc5b4\ub5a4 \uc5f4\ub9b0 \uad6c\uac04\uc5d0\uc11c\ub3c4 $f'(x)$\uac00 \ud56d\uc0c1 $0$\uc774 \ub418\uc9c0 \uc54a\ub294\ub2e4\uba74 \ud568\uc218 $f(x)$\ub294 \uadf8 \uad6c\uac04\uc5d0\uc11c \uc99d\uac00\ud55c\ub2e4\uace0 \ub9d0\ud569\ub2c8\ub2e4. \ub9c8\ucc2c\uac00\uc9c0\ub85c $f'(x) \\leq 0$\uc778 \uacbd\uc6b0\uc5d0\ub3c4 \ub3d9\uc77c\ud55c \ub17c\ub9ac\uac00 \uc801\uc6a9\ub429\ub2c8\ub2e4. \uc989, \ub3c4\ud568\uc218\uc758 \ubd80\ud638\ub294 \ud568\uc218\uc758 \uadf8\ub798\ud504\uac00 \uc704\ub85c \uc62c\ub77c\uac00\ub294\uc9c0, \uc544\ub2c8\uba74 \uc544\ub798\ub85c \ub0b4\ub824\uac00\ub294\uc9c0\ub97c \uacb0\uc815\uc9d3\ub294 \ud575\uc2ec\uc801\uc778 \uc9c0\ud45c\uac00 \ub429\ub2c8\ub2e4.\",   \"\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud1b5\ud574 \ub3c4\ud568\uc218\uc758 \ubd80\ud638\ub97c \ud65c\uc6a9\ud558\ub294 \ubc29\ubc95\uc744 \uc54c\uc544\ubd05\uc2dc\ub2e4. \ud568\uc218 $f(x) = x^3 - 3x^2 + 2$\uac00 \uc99d\uac00\ud558\ub294 \uad6c\uac04\uacfc \uac10\uc18c\ud558\ub294 \uad6c\uac04\uc744 \uad6c\ud574\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \ud568\uc218\ub97c \ubbf8\ubd84\ud558\uc5ec \ub3c4\ud568\uc218\ub97c \uad6c\ud558\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$f'(x) = 3x^2 - 6x$$\",   \"\ub3c4\ud568\uc218\uc758 \ubd80\ud638\ub97c \uc870\uc0ac\ud558\uae30 \uc704\ud574 $f'(x) = 0$\uc774 \ub418\ub294 \uc9c0\uc810\uc744 \ucc3e\uc2b5\ub2c8\ub2e4. $$3x(x - 2) = 0$$ \uc774 \uc2dd\uc744 \ud480\uba74 $x = 0$ \ub610\ub294 $x = 2$\uac00 \ub429\ub2c8\ub2e4. \uc774\uc81c \uc774 \ub450 \uc9c0\uc810\uc744 \uae30\uc900\uc73c\ub85c \uad6c\uac04\uc744 \ub098\ub204\uc5b4 \ub3c4\ud568\uc218\uc758 \ubd80\ud638\ub97c \ud655\uc778\ud569\ub2c8\ub2e4. $x < 0$\uc778 \uad6c\uac04\uc5d0\uc11c\ub294 $f'(x) > 0$\uc774\ubbc0\ub85c \ud568\uc218\ub294 \uc99d\uac00\ud558\uace0, $0 < x < 2$\uc778 \uad6c\uac04\uc5d0\uc11c\ub294 $f'(x) < 0$\uc774\ubbc0\ub85c \ud568\uc218\ub294 \uac10\uc18c\ud569\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9\uc73c\ub85c $x > 2$\uc778 \uad6c\uac04\uc5d0\uc11c\ub294 \ub2e4\uc2dc $f'(x) > 0$\uc774 \ub418\uc5b4 \ud568\uc218\ub294 \uc99d\uac00\ud558\uac8c \ub429\ub2c8\ub2e4.\",   \"\uacb0\uacfc\uc801\uc73c\ub85c \ud568\uc218 $f(x) = x^3 - 3x^2 + 2$\ub294 \uad6c\uac04 $(-\\\\infty, 0]$\uacfc $[2, \\\\infty)$\uc5d0\uc11c \uc99d\uac00\ud558\uba70, \uad6c\uac04 $[0, 2]$\uc5d0\uc11c \uac10\uc18c\ud55c\ub2e4\ub294 \uacb0\ub860\uc744 \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ucc98\ub7fc \ub3c4\ud568\uc218\uc758 \ubd80\ud638\ub97c \uc870\uc0ac\ud558\ub294 \uacfc\uc815\uc740 \ud568\uc218\uc758 \uac1c\ud615\uc744 \ud30c\uc545\ud558\ub294 \uac00\uc7a5 \uae30\ucd08\uc801\uc774\uba74\uc11c\ub3c4 \uc911\uc694\ud55c \ub2e8\uacc4\uc785\ub2c8\ub2e4. \uc5ec\ub7ec\ubd84\ub3c4 \ub2e4\uc591\ud55c \ub2e4\ud56d\ud568\uc218\ub97c \ubbf8\ubd84\ud574\ubcf4\uace0, \ub3c4\ud568\uc218\uac00 0\uc774 \ub418\ub294 \uc9c0\uc810\uc744 \ucc3e\uc544 \uadf8\ub798\ud504\uc758 \ubaa8\uc591\uc744 \uc9c1\uc811 \uadf8\ub824\ubcf4\ub294 \uc5f0\uc2b5\uc744 \ud574\ubcf4\uae38 \ubc14\ub78d\ub2c8\ub2e4.\" ]"],ai0),ag9,B.p)],ai2),ag9,B.p)],ai3),s3,s3,s3,"concept_\ub3c4\ud568\uc218\uc758\ubd80\ud638",0,"","\ubbf8\uc801\ubd84\u2160 > \ud568\uc218\uc758\uc99d\uac00\uc640\uac10\uc18c > \ub3c4\ud568\uc218\uc758\ubd80\ud638",q5,ag9,s3)
q6=A.a(["\uacf5\ud1b5\uc218\ud5591","\uc774\ucc28\ud568\uc218","\uc774\ucc28\ud568\uc218\uc640\uc774\ucc28\ubd80\ub4f1\uc2dd"],ai0)
q6=A.av(s2,A.a([A.au(A.a(["\uacf5\ud1b5\uc218\ud5591 > \uc774\ucc28\ud568\uc218 > \uc774\ucc28\ud568\uc218\uc640\uc774\ucc28\ubd80\ub4f1\uc2dd \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.r,A.a(["\uc774\ucc28\ud568\uc218 $y = ax^2 + bx + c$ ($a \\neq 0$)\uc758 \uadf8\ub798\ud504\ub294 \ud3ec\ubb3c\uc120 \ubaa8\uc591\uc744 \ub760\uba70, \uc774 \uadf8\ub798\ud504\uc640 $x$\ucd95\uc758 \uc704\uce58 \uad00\uacc4\ub294 \uc774\ucc28\ubc29\uc815\uc2dd $ax^2 + bx + c = 0$\uc758 \ud310\ubcc4\uc2dd $D = b^2 - 4ac$\uc758 \uac12\uc5d0 \ub530\ub77c \uacb0\uc815\ub429\ub2c8\ub2e4. \uc774\ucc28\ubd80\ub4f1\uc2dd $ax^2 + bx + c > 0$ \ub610\ub294 $ax^2 + bx + c < 0$\uc744 \ud47c\ub2e4\ub294 \uac83\uc740, \uc774\ucc28\ud568\uc218\uc758 \uadf8\ub798\ud504\uac00 $x$\ucd95\ubcf4\ub2e4 \uc704\ucabd\uc5d0 \uc788\uac70\ub098 \uc544\ub798\ucabd\uc5d0 \uc788\ub294 $x$\uc758 \uac12\uc758 \ubc94\uc704\ub97c \ucc3e\ub294 \uac83\uacfc \uac19\uc2b5\ub2c8\ub2e4.","\uc774\ucc28\ubd80\ub4f1\uc2dd\uc744 \ud480\uae30 \uc704\ud574\uc11c\ub294 \uba3c\uc800 \uc774\ucc28\ubc29\uc815\uc2dd $ax^2 + bx + c = 0$\uc758 \ub450 \uc2e4\uadfc\uc744 $\\alpha, \\beta$ ($\\alpha < \\beta$)\ub77c \ud560 \ub54c, $a > 0$\uc778 \uacbd\uc6b0 \ub2e4\uc74c\uacfc \uac19\uc740 \uc131\uc9c8\uc744 \uc774\uc6a9\ud569\ub2c8\ub2e4. $ax^2 + bx + c > 0$\uc758 \ud574\ub294 $x < \\alpha$ \ub610\ub294 $x > \\beta$\uc774\uace0, $ax^2 + bx + c < 0$\uc758 \ud574\ub294 $\\alpha < x < \\beta$\uc785\ub2c8\ub2e4. \ub9cc\uc57d \ud310\ubcc4\uc2dd $D=0$\uc774\ub77c\uba74 \uadf8\ub798\ud504\uac00 $x$\ucd95\uc5d0 \uc811\ud558\ubbc0\ub85c \ud574\ub294 \ud2b9\uc218\ud55c \ud615\ud0dc\uac00 \ub418\uba70, $D < 0$\uc774\uba74 \uadf8\ub798\ud504\uac00 \ud56d\uc0c1 $x$\ucd95 \uc704\uc5d0 \ub5a0 \uc788\uc5b4 \ud574\uac00 \ubaa8\ub4e0 \uc2e4\uc218\uac00 \ub418\uac70\ub098 \ud574\uac00 \uc5c6\uc744 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud1b5\ud574 \ud655\uc778\ud574 \ubd05\uc2dc\ub2e4. \uc774\ucc28\ubd80\ub4f1\uc2dd $x^2 - 5x + 6 < 0$\uc744 \ud480\uc5b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uc774 \uc2dd\uc5d0 \ub300\uc751\ud558\ub294 \uc774\ucc28\ubc29\uc815\uc2dd $x^2 - 5x + 6 = 0$\uc744 \uc778\uc218\ubd84\ud574\ud558\uba74 $(x - 2)(x - 3) = 0$\uc774 \ub418\uc5b4 \ub450 \uadfc\uc740 $x = 2$\uc640 $x = 3$\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\ucc28\ud568\uc218 $y = x^2 - 5x + 6$\uc758 \uadf8\ub798\ud504\ub294 \uc544\ub798\ub85c \ubcfc\ub85d\ud55c \ud3ec\ubb3c\uc120\uc774\uba70 $x$\ucd95\uacfc \ub450 \uc810 $(2, 0)$\uacfc $(3, 0)$\uc5d0\uc11c \ub9cc\ub0a9\ub2c8\ub2e4. \ubd80\ub4f1\uc2dd\uc5d0\uc11c $0$\ubcf4\ub2e4 \uc791\uc740 \ubc94\uc704\ub97c \uad6c\ud558\ub77c\uace0 \ud588\uc73c\ubbc0\ub85c, \uadf8\ub798\ud504\uac00 $x$\ucd95\ubcf4\ub2e4 \uc544\ub798\ucabd\uc5d0 \uc704\uce58\ud558\ub294 \uad6c\uac04\uc744 \ucc3e\uc73c\uba74 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uad6c\ud558\ub294 \ud574\ub294 $2 < x < 3$\uc774 \ub429\ub2c8\ub2e4.","\ub610 \ub2e4\ub978 \uc608\ub85c $x^2 - 2x - 3 \\geq 0$\uc744 \ud480\uc5b4\ubd05\uc2dc\ub2e4. \uba3c\uc800 \ubc29\uc815\uc2dd $x^2 - 2x - 3 = 0$\uc744 \uc778\uc218\ubd84\ud574\ud558\uba74 $(x + 1)(x - 3) = 0$\uc774 \ub418\uc5b4 \uadfc\uc740 $x = -1$\uacfc $x = 3$\uc785\ub2c8\ub2e4. \uadf8\ub798\ud504\ub294 \uc544\ub798\ub85c \ubcfc\ub85d\ud558\uace0 $x$\ucd95\uacfc \ub450 \uc810\uc5d0\uc11c \ub9cc\ub0a9\ub2c8\ub2e4.","\uc774 \ubd80\ub4f1\uc2dd\uc740 $0$\ubcf4\ub2e4 \ud06c\uac70\ub098 \uac19\uc740 \ubc94\uc704\ub97c \ucc3e\ub294 \uac83\uc774\ubbc0\ub85c, \uadf8\ub798\ud504\uac00 $x$\ucd95 \uc704\ucabd\uc5d0 \uc788\uac70\ub098 $x$\ucd95\uacfc \ub9cc\ub098\ub294 \uc9c0\uc810\uc744 \ud3ec\ud568\ud574\uc57c \ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c \uadf8\ub798\ud504\uc758 \uc591 \ub05d\ubd80\ubd84\uc5d0 \ud574\ub2f9\ud558\ub294 \ubc94\uc704\uc778 $x \\leq -1$ \ub610\ub294 $x \\geq 3$\uc774 \ucd5c\uc885\uc801\uc778 \ud574\uac00 \ub429\ub2c8\ub2e4."],ai0),ah0,B.p)],ai2),ah0,B.p)],ai3),s3,s3,s3,"concept_\uc774\ucc28\ud568\uc218\uc640\uc774\ucc28\ubd80\ub4f1\uc2dd",0,"","\uacf5\ud1b5\uc218\ud5591 > \uc774\ucc28\ud568\uc218 > \uc774\ucc28\ud568\uc218\uc640\uc774\ucc28\ubd80\ub4f1\uc2dd",q6,ah0,s3)
q7=A.a(["\uacf5\ud1b5\uc218\ud5592","\uba85\uc81c","\uba85\uc81c\uc758\uc5ed\uacfc\ub300\uc6b0","\uc774"],ai0)
q7=A.av(s2,A.a([A.au(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uba85\uc81c > \uba85\uc81c\uc758\uc5ed\uacfc\ub300\uc6b0 > \uc774 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.r,A.a(["\uba85\uc81c\uc5d0\uc11c '\uc774(Converse)'\ub780 \uc8fc\uc5b4\uc9c4 \uc870\uac74\uba85\uc81c '$p \\rightarrow q$'\uc758 \uac00\uc815\uacfc \uacb0\ub860\uc744 \uc11c\ub85c \ubc14\uafb8\uc5b4 \ub9cc\ub4e0 \uc0c8\ub85c\uc6b4 \uba85\uc81c\ub97c \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc6d0\ub798 \uba85\uc81c '$p \\rightarrow q$'\uc5d0\uc11c '$p$'\ub294 \uac00\uc815, '$q$'\ub294 \uacb0\ub860\uc774\ub77c\uace0 \ubd80\ub974\ub294\ub370, \uc774\ub97c \ub4a4\uc9d1\uc5b4 '$q \\rightarrow p$'\uc758 \ud615\ud0dc\ub85c \ub9cc\ub4dc\ub294 \uac83\uc774 \ubc14\ub85c '\uc774'\uc785\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 '\ube44\uac00 \uc624\uba74 \ub545\uc774 \uc816\ub294\ub2e4'\ub77c\ub294 \uba85\uc81c\uac00 \uc788\ub2e4\uba74, \uc774 \uba85\uc81c\uc758 \uc774\ub294 '\ub545\uc774 \uc816\uc73c\uba74 \ube44\uac00 \uc628\ub2e4'\uac00 \ub429\ub2c8\ub2e4.","\uba85\uc81c\uc758 '\uc774'\ub97c \ub2e4\ub8f0 \ub54c \uc8fc\uc758\ud560 \uc810\uc740 \uc6d0\ub798 \uba85\uc81c\uc758 \ucc38\uacfc \uac70\uc9d3\uc774 \uadf8 '\uc774'\uc758 \ucc38\uacfc \uac70\uc9d3\uacfc \ud56d\uc0c1 \uc77c\uce58\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4\ub294 \uac83\uc785\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 'x\uac00 4\uc758 \ubc30\uc218\uc774\uba74 x\ub294 \uc9dd\uc218\uc774\ub2e4'\ub77c\ub294 \uba85\uc81c\ub294 \ucc38\uc774\uc9c0\ub9cc, \uadf8 '\uc774'\uc778 'x\uac00 \uc9dd\uc218\uc774\uba74 x\ub294 4\uc758 \ubc30\uc218\uc774\ub2e4'\ub294 2\ub098 6\uacfc \uac19\uc740 \ubc18\ub840\uac00 \uc874\uc7ac\ud558\ubbc0\ub85c \uac70\uc9d3\uc774 \ub429\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uba85\uc81c\uc640 \uadf8 \uc774\ub294 \ub17c\ub9ac\uc801\uc73c\ub85c \uc11c\ub85c \ub2e4\ub978 \uc9c4\ub9bf\uac12\uc744 \uac00\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc218\ud559\uc801\uc73c\ub85c \uba85\uc81c '$p \\rightarrow q$'\uc758 \uc774\ub97c \uae30\ud638\ub85c \ub098\ud0c0\ub0b4\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uc6d0\ub798 \uba85\uc81c\uac00 '$p \\rightarrow q$'\uc77c \ub54c, \uadf8 \uc774\ub294 $$q \\rightarrow p$$\uac00 \ub429\ub2c8\ub2e4. \ub9cc\uc57d \uc8fc\uc5b4\uc9c4 \uba85\uc81c\uc5d0 \ubd80\uc815($\\sim$)\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4\uba74, \uac00\uc815\uacfc \uacb0\ub860\uc758 \uc704\uce58\ub9cc \ubc14\uafb8\ub294 \uac83\uc774 '\uc774'\uc774\ubbc0\ub85c, '$\\sim p \\rightarrow \\sim q$'\uc758 \uc774\ub294 '$\\sim q \\rightarrow \\sim p$'\uac00 \ub428\uc744 \uae30\uc5b5\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc608\uc81c \ubb38\uc81c: \ub2e4\uc74c \uba85\uc81c\uc758 '\uc774'\ub97c \uad6c\ud558\uace0, \uc6d0\ub798 \uba85\uc81c\uc640 \uadf8 \uc774\uc758 \ucc38, \uac70\uc9d3\uc744 \ud310\ubcc4\ud558\uc2dc\uc624. [\uba85\uc81c: $x^2 = 9$\uc774\uba74 $x = 3$\uc774\ub2e4.]","\ud480\uc774 \ub2e8\uacc4 1: \uba3c\uc800 \uc8fc\uc5b4\uc9c4 \uba85\uc81c\uc758 \uac00\uc815 '$p$'\ub294 '$x^2 = 9$'\uc774\uace0, \uacb0\ub860 '$q$'\ub294 '$x = 3$'\uc785\ub2c8\ub2e4. \uc774\ub97c \uc11c\ub85c \ubc14\uafb8\uc5b4 '\uc774'\ub97c \ub9cc\ub4e4\uba74 '$x = 3$\uc774\uba74 $x^2 = 9$\uc774\ub2e4.'\uac00 \ub429\ub2c8\ub2e4. \uc6d0\ub798 \uba85\uc81c\uc5d0\uc11c $x^2 = 9$\ub97c \ub9cc\uc871\ud558\ub294 $x$\ub294 $3$\uacfc $-3$\uc774 \uc788\ub294\ub370, \uacb0\ub860\uc778 $x=3$\ub9cc\uc73c\ub85c\ub294 \uc774\ub97c \ubaa8\ub450 \uc124\uba85\ud560 \uc218 \uc5c6\uc73c\ubbc0\ub85c \uc6d0\ub798 \uba85\uc81c\ub294 \uac70\uc9d3\uc785\ub2c8\ub2e4.","\ud480\uc774 \ub2e8\uacc4 2: \uc774\uc81c \uad6c\ud55c '\uc774'\uc778 '$x = 3 \\rightarrow x^2 = 9$'\ub97c \uc0b4\ud3b4\ubd05\uc2dc\ub2e4. $x$\uac00 $3$\uc774\uba74 $x^2$\uc740 \ubc18\ub4dc\uc2dc $3^2 = 9$\uac00 \ub418\ubbc0\ub85c, \uc774 \uba85\uc81c\ub294 \ucc38\uc785\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc8fc\uc5b4\uc9c4 \uba85\uc81c\ub294 \uac70\uc9d3\uc774\uc9c0\ub9cc, \uadf8 '\uc774'\ub294 \ucc38\uc774 \ub418\ub294 \uacbd\uc6b0\uc784\uc744 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uba85\uc81c\uc640 \uadf8 \uc774\ub294 \uac01\uac01 \ub3c5\ub9bd\uc801\uc73c\ub85c \ucc38\uacfc \uac70\uc9d3\uc744 \ud310\ubcc4\ud574\uc57c \ud569\ub2c8\ub2e4."],ai0),"\uc774",B.p)],ai2),"\uc774",B.p)],ai3),s3,s3,s3,"concept_\uc774",0,"","\uacf5\ud1b5\uc218\ud5592 > \uba85\uc81c > \uba85\uc81c\uc758\uc5ed\uacfc\ub300\uc6b0 > \uc774",q7,"\uc774",s3)
q8=A.a(["\ub300\uc218","\uc218\uc5f4","\ud569\uc758\uae30\ud638\uc2dc\uadf8\ub9c8","\uc2dc\uadf8\ub9c8\uacf5\uc2dd"],ai0)
q8=A.av(s2,A.a([A.au(A.a(["\ub300\uc218 > \uc218\uc5f4 > \ud569\uc758\uae30\ud638\uc2dc\uadf8\ub9c8 > \uc2dc\uadf8\ub9c8\uacf5\uc2dd \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.r,A.a(["\uc218\uc5f4\uc758 \ud569\uc744 \ub098\ud0c0\ub0b4\ub294 \uae30\ud638\uc778 \uc2dc\uadf8\ub9c8($\\sum$)\ub294 \ubcf5\uc7a1\ud55c \uc218\uc5f4\uc758 \ud569\uc744 \uac04\uacb0\ud558\uac8c \ud45c\ud604\ud558\uae30 \uc704\ud574 \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \uc2dc\uadf8\ub9c8 \uae30\ud638 \uc544\ub798\uc5d0\ub294 \ubcc0\uc218\uc640 \uc2dc\uc791 \uac12\uc744, \uc704\uc5d0\ub294 \ub05d \uac12\uc744 \uc801\uc5b4 \uc218\uc5f4\uc758 \ud56d\ub4e4\uc744 \uc5b4\ub514\ubd80\ud130 \uc5b4\ub514\uae4c\uc9c0 \ub354\ud560\uc9c0 \uba85\uc2dc\ud569\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \uc218\uc5f4 $a_n$\uc758 \uccab\uc9f8 \ud56d\ubd80\ud130 \uc81c$n$\ud56d\uae4c\uc9c0\uc758 \ud569\uc740 $\\sum_{k=1}^{n} a_k$\uc640 \uac19\uc774 \ub098\ud0c0\ub0b4\uba70, \uc774\ub294 $a_1 + a_2 + \\dots + a_n$\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4.","\uc2dc\uadf8\ub9c8\ub294 \ud569\uc758 \uc131\uc9c8\uc5d0 \ub530\ub77c \uba87 \uac00\uc9c0 \uc911\uc694\ud55c \uacf5\uc2dd\ub4e4\uc744 \uac00\uc9d1\ub2c8\ub2e4. \uac00\uc7a5 \uae30\ubcf8\uc774 \ub418\ub294 \uacf5\uc2dd\uc740 \uc790\uc5f0\uc218\uc758 \uac70\ub4ed\uc81c\uacf1\uc758 \ud569\uc785\ub2c8\ub2e4. \uccab\uc9f8, \uc790\uc5f0\uc218 $k$\uc758 \ud569\uc740 $$\\sum_{k=1}^{n} k = \\frac{n(n+1)}{2}$$ \uc774\uace0, \ub458\uc9f8, \uc81c\uacf1\uc758 \ud569\uc740 $$\\sum_{k=1}^{n} k^2 = \\frac{n(n+1)(2n+1)}{6}$$ \uc785\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc138\uc81c\uacf1\uc758 \ud569\uc740 $$\\sum_{k=1}^{n} k^3 = \\left\\{ \\frac{n(n+1)}{2} \\right\\}^2$$ \uc640 \uac19\uc774 \uc815\uc758\ub429\ub2c8\ub2e4.","\uc2dc\uadf8\ub9c8\ub294 \uc120\ud615\uc131\uc744 \uac00\uc9c0\uace0 \uc788\uc5b4, \uc0c1\uc218\ubc30\ub098 \ub367\uc148, \ube84\uc148\uc5d0 \ub300\ud574 \ubd84\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc989, $c$\uac00 \uc0c1\uc218\uc77c \ub54c $$\\sum_{k=1}^{n} c a_k = c \\sum_{k=1}^{n} a_k$$ \uac00 \uc131\ub9bd\ud558\uba70, $$\\sum_{k=1}^{n} (a_k \\pm b_k) = \\sum_{k=1}^{n} a_k \\pm \\sum_{k=1}^{n} b_k$$ \uc640 \uac19\uc774 \uac01\uac01\uc758 \ud569\uc73c\ub85c \ub098\ub204\uc5b4 \uacc4\uc0b0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub610\ud55c, \uc0c1\uc218 $c$\ub97c $n$\ubc88 \ub354\ud558\uba74 $$\\sum_{k=1}^{n} c = cn$$ \uc774 \ub41c\ub2e4\ub294 \uc810\ub3c4 \uae30\uc5b5\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc774\uc81c \uc608\uc81c\ub97c \ud1b5\ud574 \uc2dc\uadf8\ub9c8 \uacf5\uc2dd\uc744 \uc801\uc6a9\ud574 \ubd05\uc2dc\ub2e4. \ubb38\uc81c: $\\sum_{k=1}^{10} (2k + 3)$\uc758 \uac12\uc744 \uad6c\ud558\uc2dc\uc624. \uc774 \uc2dd\uc740 \uc2dc\uadf8\ub9c8\uc758 \uc131\uc9c8\uc744 \uc774\uc6a9\ud558\uc5ec \ub450 \ubd80\ubd84\uc73c\ub85c \ub098\ub20c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc989, $$\\sum_{k=1}^{10} 2k + \\sum_{k=1}^{10} 3$$ \uc73c\ub85c \ubd84\ub9ac\ud569\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uc0c1\uc218 2\ub97c \uc55e\uc73c\ub85c \ube7c\ub0b4\uba74 $2 \\sum_{k=1}^{10} k + \\sum_{k=1}^{10} 3$\uc774 \ub429\ub2c8\ub2e4.","\uc774\uc81c \uc704\uc5d0\uc11c \ubc30\uc6b4 \uacf5\uc2dd\uc744 \ub300\uc785\ud558\uc5ec \uacc4\uc0b0\ud569\ub2c8\ub2e4. \uccab \ubc88\uc9f8 \ud56d\uc740 $2 \\times \\frac{10(10+1)}{2} = 10 \\times 11 = 110$\uc774 \ub418\uace0, \ub450 \ubc88\uc9f8 \ud56d\uc740 \uc0c1\uc218\ub97c 10\ubc88 \ub354\ud558\ub294 \uac83\uc774\ubbc0\ub85c $3 \\times 10 = 30$\uc774 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc804\uccb4 \ud569\uc740 $110 + 30 = 140$\uc785\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uc2dc\uadf8\ub9c8 \uacf5\uc2dd\uc744 \ud65c\uc6a9\ud558\uba74 \uc77c\uc77c\uc774 \uc22b\uc790\ub97c \ub354\ud558\uc9c0 \uc54a\uace0\ub3c4 \ube60\ub974\uace0 \uc815\ud655\ud558\uac8c \uc218\uc5f4\uc758 \ud569\uc744 \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),ah1,B.p)],ai2),ah1,B.p)],ai3),s3,s3,s3,"concept_\uc2dc\uadf8\ub9c8\uacf5\uc2dd",0,"","\ub300\uc218 > \uc218\uc5f4 > \ud569\uc758\uae30\ud638\uc2dc\uadf8\ub9c8 > \uc2dc\uadf8\ub9c8\uacf5\uc2dd",q8,ah1,s3)
q9=A.a(["\uacf5\ud1b5\uc218\ud5591","\ub2e4\ud56d\uc2dd","\ub098\uba38\uc9c0\uc815\ub9ac","\ub098\uba38\uc9c0\uc815\ub9ac\ud65c\uc6a9"],ai0)
q9=A.av(s2,A.a([A.au(A.a(["\uacf5\ud1b5\uc218\ud5591 > \ub2e4\ud56d\uc2dd > \ub098\uba38\uc9c0\uc815\ub9ac > \ub098\uba38\uc9c0\uc815\ub9ac\ud65c\uc6a9 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.r,A.a(["\ub098\uba38\uc9c0\uc815\ub9ac\ub780 \ub2e4\ud56d\uc2dd $P(x)$\ub97c \uc77c\ucc28\uc2dd $x-a$\ub85c \ub098\ub204\uc5c8\uc744 \ub54c\uc758 \ub098\uba38\uc9c0\uac00 $P(a)$\uc640 \uac19\ub2e4\ub294 \ub9e4\uc6b0 \uc720\uc6a9\ud55c \uc131\uc9c8\uc785\ub2c8\ub2e4. \uc774\ub97c \ud65c\uc6a9\ud558\uba74 \ub2e4\ud56d\uc2dd\uc744 \uc2e4\uc81c\ub85c \ub098\ub204\uc9c0 \uc54a\uace0\ub3c4 \ub098\uba38\uc9c0\ub97c \ube60\ub974\uac8c \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub9cc\uc57d \ub2e4\ud56d\uc2dd $P(x)$\ub97c \uc774\ucc28\uc2dd $(x-a)(x-b)$\ub85c \ub098\ub204\ub294 \uacbd\uc6b0, \ub098\uba38\uc9c0\ub294 \uc77c\ucc28\uc2dd \ud615\ud0dc\uc778 $ax+b$\ub85c \uac00\uc815\ud558\uc5ec \ubb38\uc81c\ub97c \ud574\uacb0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub54c \ub098\ub204\ub294 \uc2dd\uc744 $P(x) = (x-a)(x-b)Q(x) + ax+b$\uc640 \uac19\uc774 \ud56d\ub4f1\uc2dd\uc73c\ub85c \ud45c\ud604\ud558\ub294 \uac83\uc774 \ud575\uc2ec\uc785\ub2c8\ub2e4.","\ub098\uba38\uc9c0\uc815\ub9ac\ub97c \ud65c\uc6a9\ud560 \ub54c \uac00\uc7a5 \uc911\uc694\ud55c \uac83\uc740 \ub098\ub204\ub294 \uc2dd\uc758 \uc778\uc218\ubd84\ud574 \uac00\ub2a5 \uc5ec\ubd80\uc785\ub2c8\ub2e4. \ub098\ub204\ub294 \uc2dd\uc774 $(x-a)^2$\uacfc \uac19\uc774 \uc644\uc804\uc81c\uacf1\uc2dd\uc778 \uacbd\uc6b0\uc5d0\ub294 \uc218\uce58\ub300\uc785\ubc95\uc744 \ud55c \ubc88\ub9cc \uc0ac\uc6a9\ud560 \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0, \ubbf8\ubd84\ubc95\uc744 \uc774\uc6a9\ud558\uac70\ub098 \uc2dd\uc744 \ubcc0\ud615\ud558\uc5ec \ub098\uba38\uc9c0 $R(x)$\ub97c \uad6c\ud569\ub2c8\ub2e4. \ub610\ud55c, \ub098\ub204\ub294 \uc2dd\uc774 \uc778\uc218\ubd84\ud574\ub418\uc9c0 \uc54a\ub294 \uc774\ucc28\uc2dd\uc77c \ub54c\ub294 \uc9c1\uc811\uc801\uc778 \ub300\uc785\ubcf4\ub2e4\ub294 \uacc4\uc218 \ube44\uad50\ubc95\uc774\ub098 \uc2dd\uc758 \uad6c\uc870\uc801 \ud2b9\uc9d5\uc744 \ud65c\uc6a9\ud558\uc5ec \ub098\uba38\uc9c0\ub97c \uacb0\uc815\ud558\uac8c \ub429\ub2c8\ub2e4.","\uc608\uc81c \ubb38\uc81c: \ub2e4\ud56d\uc2dd $P(x)$\ub97c $(x-1)$\ub85c \ub098\ub204\uba74 \ub098\uba38\uc9c0\uac00 2\uc774\uace0, $(x-2)$\ub85c \ub098\ub204\uba74 \ub098\uba38\uc9c0\uac00 3\uc785\ub2c8\ub2e4. \uc774\ub54c $P(x)$\ub97c $(x-1)(x-2)$\ub85c \ub098\ub208 \ub098\uba38\uc9c0\ub97c \uad6c\ud558\uc2dc\uc624. \uc774 \ubb38\uc81c\ub97c \ud480\uae30 \uc704\ud574 \uba3c\uc800 \ub098\uba38\uc9c0\uc815\ub9ac\uc5d0 \uc758\ud574 $P(1)=2$, $P(2)=3$\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uad6c\ud558\ub294 \ub098\uba38\uc9c0\ub97c $R(x)=ax+b$\ub77c\uace0 \ud558\uba74, $P(x) = (x-1)(x-2)Q(x) + ax+b$\ub77c\ub294 \ud56d\ub4f1\uc2dd\uc744 \uc138\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uc704 \ud56d\ub4f1\uc2dd\uc5d0 $x=1$\uacfc $x=2$\ub97c \ucc28\ub840\ub300\ub85c \ub300\uc785\ud558\uc5ec \uc5f0\ub9bd\ubc29\uc815\uc2dd\uc744 \ub9cc\ub4ed\ub2c8\ub2e4. $x=1$\uc744 \ub300\uc785\ud558\uba74 $P(1) = a(1) + b = 2$\uac00 \ub418\uace0, $x=2$\ub97c \ub300\uc785\ud558\uba74 $P(2) = a(2) + b = 3$\uc774 \ub429\ub2c8\ub2e4. \uc774 \ub450 \uc2dd\uc744 \uc5f0\ub9bd\ud558\uba74 $a+b=2$\uc640 $2a+b=3$\uc774 \ub098\uc635\ub2c8\ub2e4. \uc544\ub798 \uc2dd\uc5d0\uc11c \uc704 \uc2dd\uc744 \ube7c\uba74 $a=1$\uc744 \uc5bb\uace0, \uc774\ub97c \ub2e4\uc2dc \ub300\uc785\ud558\uba74 $b=1$\uc774 \ub428\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ub530\ub77c\uc11c \uc6b0\ub9ac\uac00 \uad6c\ud558\uace0\uc790 \ud558\ub294 \ub098\uba38\uc9c0 $R(x)$\ub294 $ax+b$\uc5d0 $a=1, b=1$\uc744 \ub300\uc785\ud55c $x+1$\uc774 \ub429\ub2c8\ub2e4. \uc774\ucc98\ub7fc \ub098\uba38\uc9c0\uc815\ub9ac\ub97c \ud65c\uc6a9\ud558\uba74 \ubcf5\uc7a1\ud55c \ub2e4\ud56d\uc2dd\uc758 \ub098\ub217\uc148 \uacfc\uc815\uc744 \uac70\uce58\uc9c0 \uc54a\uace0\ub3c4, \ub098\ub204\ub294 \uc2dd\uc758 \uadfc\uc744 \ub300\uc785\ud558\ub294 \uac83\ub9cc\uc73c\ub85c \ub098\uba38\uc9c0\ub97c \uc815\ud655\ud558\uac8c \ucc3e\uc544\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \ubc29\ubc95\uc740 \uace0\ub4f1 \uc218\ud559\uc5d0\uc11c \ub2e4\ud56d\uc2dd\uc758 \uc131\uc9c8\uc744 \uc774\ud574\ud558\uace0 \ubb38\uc81c\ub97c \ud6a8\uc728\uc801\uc73c\ub85c \ud574\uacb0\ud558\ub294 \ub370 \ud544\uc218\uc801\uc778 \ub3c4\uad6c\uc785\ub2c8\ub2e4."],ai0),ah2,B.p)],ai2),ah2,B.p)],ai3),s3,s3,s3,"concept_\ub098\uba38\uc9c0\uc815\ub9ac\ud65c\uc6a9",0,"","\uacf5\ud1b5\uc218\ud5591 > \ub2e4\ud56d\uc2dd > \ub098\uba38\uc9c0\uc815\ub9ac > \ub098\uba38\uc9c0\uc815\ub9ac\ud65c\uc6a9",q9,ah2,s3)
r0=A.a(["\uacf5\ud1b5\uc218\ud5592","\uc88c\ud45c\ud3c9\uba74","\uc9c1\uc120\uc758\ubc29\uc815\uc2dd","\uae30\uc6b8\uae30"],ai0)
r0=A.av(s2,A.a([A.au(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \uc9c1\uc120\uc758\ubc29\uc815\uc2dd > \uae30\uc6b8\uae30 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.r,A.a(["\uc88c\ud45c\ud3c9\uba74\uc5d0\uc11c \uc9c1\uc120\uc758 \uae30\uc6b8\uae30\ub294 \uc9c1\uc120\uc774 \uc5bc\ub9c8\ub098 \uac00\ud30c\ub974\uac8c \uae30\uc6b8\uc5b4\uc838 \uc788\ub294\uc9c0\ub97c \ub098\ud0c0\ub0b4\ub294 \ucc99\ub3c4\uc785\ub2c8\ub2e4. \uc9c1\uc120 \uc704\uc758 \uc11c\ub85c \ub2e4\ub978 \ub450 \uc810 $A(x_1, y_1)$\uacfc $B(x_2, y_2)$\ub97c \uc9c0\ub0a0 \ub54c, \uae30\uc6b8\uae30\ub294 '$x$\uc758 \uc99d\uac00\ub7c9\uc5d0 \ub300\ud55c $y$\uc758 \uc99d\uac00\ub7c9\uc758 \ube44\uc728'\ub85c \uc815\uc758\ud569\ub2c8\ub2e4. \uc989, $x$\uac12\uc774 $x_1$\uc5d0\uc11c $x_2$\ub85c \ubcc0\ud560 \ub54c $y$\uac12\uc774 $y_1$\uc5d0\uc11c $y_2$\ub85c \ubcc0\ud55c\ub2e4\uba74, \uae30\uc6b8\uae30 $m$\uc740 \ub2e4\uc74c\uacfc \uac19\uc740 \uacf5\uc2dd\uc73c\ub85c \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uae30\uc6b8\uae30 $m$\uc744 \uad6c\ud558\ub294 \uacf5\uc2dd\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$m = \\frac{y_2 - y_1}{x_2 - x_1} = \\frac{\\Delta y}{\\Delta x} \\quad (x_1 \\neq x_2)$$ \uc774 \uc2dd\uc5d0\uc11c \ubd84\ubaa8\uc778 $x_2 - x_1$\uc740 $x$\uc758 \ubcc0\ud654\ub7c9, \ubd84\uc790\uc778 $y_2 - y_1$\uc740 $y$\uc758 \ubcc0\ud654\ub7c9\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \ub9cc\uc57d $x_1 = x_2$\ub77c\uba74 \ubd84\ubaa8\uac00 0\uc774 \ub418\uc5b4 \uae30\uc6b8\uae30\ub97c \uc815\uc758\ud560 \uc218 \uc5c6\ub294\ub370, \uc774\ub294 \uc9c1\uc120\uc774 $y$\ucd95\uacfc \ud3c9\ud589\ud55c \uc218\uc9c1\uc120\uc778 \uacbd\uc6b0\ub97c \ub73b\ud569\ub2c8\ub2e4.","\uae30\uc6b8\uae30\uc758 \ubd80\ud638\ub294 \uc9c1\uc120\uc758 \ubc29\ud5a5\uc744 \uacb0\uc815\ud569\ub2c8\ub2e4. \uae30\uc6b8\uae30\uac00 \uc591\uc218($m > 0$)\uc774\uba74 \uc624\ub978\ucabd \uc704\ub85c \ud5a5\ud558\ub294 \uc9c1\uc120\uc774 \ub418\uace0, \uae30\uc6b8\uae30\uac00 \uc74c\uc218($m < 0$)\uc774\uba74 \uc624\ub978\ucabd \uc544\ub798\ub85c \ud5a5\ud558\ub294 \uc9c1\uc120\uc774 \ub429\ub2c8\ub2e4. \ub610\ud55c \uae30\uc6b8\uae30\uac00 0($m = 0$)\uc774\uba74 $x$\ucd95\uacfc \ud3c9\ud589\ud55c \uc218\ud3c9\uc120\uc774 \ub429\ub2c8\ub2e4. \uae30\uc6b8\uae30\uc758 \uc808\ub313\uac12\uc774 \ud074\uc218\ub85d \uc9c1\uc120\uc740 $y$\ucd95\uc5d0 \ub354 \uac00\uae5d\uac8c \uac00\ud30c\ub974\uac8c \uc11c \uc788\uac8c \ub429\ub2c8\ub2e4.","\uc608\uc81c: \ub450 \uc810 $A(1, 2)$\uc640 $B(3, 6)$\uc744 \uc9c0\ub098\ub294 \uc9c1\uc120\uc758 \uae30\uc6b8\uae30\ub97c \uad6c\ud574 \ubd05\uc2dc\ub2e4. \uba3c\uc800 \uacf5\uc2dd\uc5d0 \uac01 \uc810\uc758 \uc88c\ud45c\ub97c \ub300\uc785\ud569\ub2c8\ub2e4. \uc5ec\uae30\uc11c $x_1=1, y_1=2$\uc774\uace0 $x_2=3, y_2=6$\uc785\ub2c8\ub2e4. \uae30\uc6b8\uae30 $m$\uc740 \ub2e4\uc74c\uacfc \uac19\uc774 \uacc4\uc0b0\ub429\ub2c8\ub2e4. $$m = \\frac{6 - 2}{3 - 1} = \\frac{4}{2} = 2$$ \ub530\ub77c\uc11c \uc774 \uc9c1\uc120\uc758 \uae30\uc6b8\uae30\ub294 2\uc785\ub2c8\ub2e4.","\uc704\uc758 \uacb0\uacfc\uc5d0\uc11c \uae30\uc6b8\uae30\uac00 2\ub77c\ub294 \uac83\uc740 $x$\uac12\uc774 1\ub9cc\ud07c \uc99d\uac00\ud560 \ub54c $y$\uac12\uc740 2\ub9cc\ud07c \uc99d\uac00\ud55c\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4. \ub9cc\uc57d \uc810 $A$\uc5d0\uc11c \uc2dc\uc791\ud558\uc5ec $x$\ucd95 \ubc29\ud5a5\uc73c\ub85c 1\ub9cc\ud07c, $y$\ucd95 \ubc29\ud5a5\uc73c\ub85c 2\ub9cc\ud07c \uc774\ub3d9\ud558\uba74 \uc810 $(1+1, 2+2) = (2, 4)$\uc5d0 \ub3c4\ub2ec\ud558\uac8c \ub418\ub294\ub370, \uc774 \uc810 \uc5ed\uc2dc \ud574\ub2f9 \uc9c1\uc120 \uc704\uc5d0 \uc874\uc7ac\ud558\uac8c \ub429\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uae30\uc6b8\uae30\ub294 \uc9c1\uc120 \uc704\uc758 \uc784\uc758\uc758 \ub450 \uc810\uc744 \uc120\ud0dd\ud574\ub3c4 \ud56d\uc0c1 \uc77c\uc815\ud558\ub2e4\ub294 \uc131\uc9c8\uc744 \uac00\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4."],ai0),"\uae30\uc6b8\uae30",B.p)],ai2),"\uae30\uc6b8\uae30",B.p)],ai3),s3,s3,s3,"concept_\uae30\uc6b8\uae30",0,"","\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \uc9c1\uc120\uc758\ubc29\uc815\uc2dd > \uae30\uc6b8\uae30",r0,"\uae30\uc6b8\uae30",s3)
r1=A.a(["\ub300\uc218","\uc9c0\uc218\ud568\uc218","\uc9c0\uc218\ud568\uc218\uc758\uadf8\ub798\ud504"],ai0)
r1=A.av(s2,A.a([A.au(A.a(["\ub300\uc218 > \uc9c0\uc218\ud568\uc218 > \uc9c0\uc218\ud568\uc218\uc758\uadf8\ub798\ud504 \uac1c\ub150 \ud559\uc2b5"],ai0),B.y,A.a([A.aw(s3,B.r,A.a(["\uc9c0\uc218\ud568\uc218\ub780 \ubcc0\uc218 $x$\uac00 \uc9c0\uc218\uc5d0 \uc788\ub294 \ud568\uc218\ub85c, \uc77c\ubc18\uc801\uc73c\ub85c $f(x) = a^x$ (\ub2e8, $a > 0, a \\neq 1$)\uc758 \uaf34\ub85c \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \uc774\ub54c $a$\ub97c \ubc11\uc774\ub77c\uace0 \ud558\uba70, \ubc11\uc758 \uac12\uc5d0 \ub530\ub77c \uadf8\ub798\ud504\uc758 \ubaa8\uc591\uc774 \uacb0\uc815\ub429\ub2c8\ub2e4. $a > 1$\uc77c \ub54c\ub294 $x$\uac00 \ucee4\uc9c8\uc218\ub85d $y$\uac12\ub3c4 \uae09\uaca9\ud788 \ucee4\uc9c0\ub294 \uc99d\uac00\ud568\uc218\uac00 \ub418\uace0, $0 < a < 1$\uc77c \ub54c\ub294 $x$\uac00 \ucee4\uc9c8\uc218\ub85d $y$\uac12\uc774 0\uc5d0 \ud55c\uc5c6\uc774 \uac00\uae4c\uc6cc\uc9c0\ub294 \uac10\uc18c\ud568\uc218\uac00 \ub429\ub2c8\ub2e4.","\uc9c0\uc218\ud568\uc218 $y = a^x$\uc758 \uadf8\ub798\ud504\ub294 \uba87 \uac00\uc9c0 \uc911\uc694\ud55c \uc131\uc9c8\uc744 \uac00\uc9d1\ub2c8\ub2e4. \uccab\uc9f8, \ubaa8\ub4e0 \uc9c0\uc218\ud568\uc218\uc758 \uadf8\ub798\ud504\ub294 $x$\uac00 \ubb34\uc5c7\uc774\ub4e0 $a^0 = 1$\uc774 \ub418\ubbc0\ub85c \ud56d\uc0c1 \uc810 $(0, 1)$\uc744 \uc9c0\ub0a9\ub2c8\ub2e4. \ub458\uc9f8, $a^x$\ub294 \ud56d\uc0c1 \uc591\uc218\uc774\ubbc0\ub85c \uadf8\ub798\ud504\ub294 $x$\ucd95\ubcf4\ub2e4 \ud56d\uc0c1 \uc704\ucabd\uc5d0 \uadf8\ub824\uc9c0\uba70, $x$\ucd95($y=0$)\uc744 \uc810\uadfc\uc120\uc73c\ub85c \uac00\uc9d1\ub2c8\ub2e4. \uc14b\uc9f8, $x$\uac12\uc774 \uc99d\uac00\ud560 \ub54c $y$\uac12\ub3c4 \uc99d\uac00\ud558\uac70\ub098 \uac10\uc18c\ud558\ub294 \uc77c\ub300\uc77c \ub300\uc751 \ud568\uc218\uc774\ubbc0\ub85c \uc5ed\ud568\uc218\uac00 \uc874\uc7ac\ud569\ub2c8\ub2e4.","\uc9c0\uc218\ud568\uc218\uc758 \uadf8\ub798\ud504\ub97c \ud3c9\ud589\uc774\ub3d9\ud558\uac70\ub098 \ub300\uce6d\uc774\ub3d9\ud558\uba74 \ub354 \ub2e4\uc591\ud55c \ud615\ud0dc\ub97c \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 $y = a^x + q$\ub294 \uc6d0\ub798 \uadf8\ub798\ud504\ub97c $y$\ucd95 \ubc29\ud5a5\uc73c\ub85c $q$\ub9cc\ud07c \ud3c9\ud589\uc774\ub3d9\ud55c \uac83\uc774\uba70, \uc774\ub85c \uc778\ud574 \uc810\uadfc\uc120\ub3c4 $y = q$\ub85c \ubcc0\ud558\uac8c \ub429\ub2c8\ub2e4. \ub610\ud55c $y = a^{-x} = (1/a)^x$\ub294 $y$\ucd95\uc5d0 \ub300\ud558\uc5ec \ub300\uce6d\uc778 \uadf8\ub798\ud504\uac00 \ub418\uc5b4, \ubc11\uc758 \uc5ed\uc218 \uad00\uacc4\uac00 \uadf8\ub798\ud504\uc758 \ub300\uce6d\uc131\uc744 \uacb0\uc815\ud55c\ub2e4\ub294 \uc810\uc744 \uc774\ud574\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc608\uc81c: \ud568\uc218 $f(x) = 2^x - 1$\uc758 \uadf8\ub798\ud504\ub97c \uadf8\ub9ac\uace0 \uc810\uadfc\uc120\uc744 \uad6c\ud558\uc2dc\uc624. \uba3c\uc800 \uae30\ubcf8\ud615\uc778 $y = 2^x$\uc758 \uadf8\ub798\ud504\ub97c \uc0dd\uac01\ud569\ub2c8\ub2e4. \uc774 \uadf8\ub798\ud504\ub294 $(0, 1)$\uc744 \uc9c0\ub098\uace0 $x$\ucd95\uc744 \uc810\uadfc\uc120\uc73c\ub85c \uac00\uc9d1\ub2c8\ub2e4. \uc8fc\uc5b4\uc9c4 \ud568\uc218\ub294 \uc774\ub97c $y$\ucd95 \ubc29\ud5a5\uc73c\ub85c $-1$\ub9cc\ud07c \ud3c9\ud589\uc774\ub3d9\ud55c \uac83\uc774\ubbc0\ub85c, \ubaa8\ub4e0 \uc810\uc758 $y$\uc88c\ud45c\uc5d0\uc11c 1\uc744 \ube8d\ub2c8\ub2e4. \ub530\ub77c\uc11c $(0, 1)$\uc740 $(0, 0)$\uc73c\ub85c \uc774\ub3d9\ud569\ub2c8\ub2e4.","\ub2e8\uacc4\ubcc4 \ud480\uc774: 1\ub2e8\uacc4, \uae30\ubcf8 \uadf8\ub798\ud504 $y = 2^x$\ub97c \uadf8\ub9bd\ub2c8\ub2e4. 2\ub2e8\uacc4, \ud568\uc218\uc2dd $y = 2^x - 1$\uc744 \ud655\uc778\ud558\uc5ec \uadf8\ub798\ud504\ub97c \uc544\ub798\ub85c 1\ub9cc\ud07c \ub0b4\ub9bd\ub2c8\ub2e4. 3\ub2e8\uacc4, \uc6d0\ub798 \uc810\uadfc\uc120\uc774 $y = 0$\uc774\uc5c8\uc73c\ubbc0\ub85c, \ud3c9\ud589\uc774\ub3d9\uc5d0 \uc758\ud574 \uc0c8\ub85c\uc6b4 \uc810\uadfc\uc120\uc740 $y = -1$\uc774 \ub429\ub2c8\ub2e4. \uacb0\uacfc\uc801\uc73c\ub85c \uc774 \uadf8\ub798\ud504\ub294 \uc810 $(0, 0)$\uc744 \uc9c0\ub098\uba70 $y = -1$\uc744 \uc810\uadfc\uc120\uc73c\ub85c \ud558\ub294 \uc99d\uac00\ud558\ub294 \uace1\uc120\uc774 \ub429\ub2c8\ub2e4."],ai0),ah3,B.p)],ai2),ah3,B.p)],ai3),s3,s3,s3,"concept_\uc9c0\uc218\ud568\uc218\uc758\uadf8\ub798\ud504",0,"","\ub300\uc218 > \uc9c0\uc218\ud568\uc218 > \uc9c0\uc218\ud568\uc218\uc758\uadf8\ub798\ud504",r1,ah3,s3)
